window.GUIDES = {
"ur": "<style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:14px}\n      .guide-content th,.guide-content td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n    </style>\n\n    <h2>hp، PS اور kW کبھی بالکل ایک دوسرے سے میل کیوں نہیں کھاتے</h2>\n    <p>طاقت کی درجہ بندیاں تین مختلف روایتوں سے آتی ہیں اور تینوں آج بھی ایک ہی اسپیک شیٹ پر نظر آتی ہیں۔ گاڑیوں کے انجن امریکہ اور برطانیہ میں ہارس پاور (hp) میں، یورپ کے بیشتر حصے، جاپان اور کوریا میں میٹرک ہارس پاور (PS) میں، اور بڑھتے ہوئے کلوواٹ (kW) میں پیش کیے جاتے ہیں، کیونکہ یورپی یونین کی ٹائپ منظوری اور برقی گاڑیوں کی تفصیلات یہی تقاضا کرتی ہیں۔ گھریلو آلات اور پمپ عام طور پر نیم پلیٹ پر واٹ یا hp میں درج ہوتے ہیں۔ ایئر کنڈیشنر اور ہیٹنگ فرنس BTU/h میں درج ہوتے ہیں۔ ان میں سے کوئی بھی الگ طبیعی مقدار بیان نہیں کرتا — یہ سب توانائی کی منتقلی کی شرحیں ہیں — لیکن انہیں یادداشت کے سہارے تبدیل کرنا ہی اسپیک شیٹ کی زیادہ تر غلطیوں کی جڑ ہے، خاص طور پر hp اور PS کے درمیان، جو بظاہر ایک جیسے لگتے ہیں مگر بالکل ایک نہیں۔</p>\n\n    <h3>استعمال کا طریقہ</h3>\n    <ol>\n      <li>اپنے پاس موجود عدد درج کریں — مثلاً انجن کی تفصیل میں دی گئی hp کی قیمت، یا آلے کے لیبل پر لکھے واٹ۔</li>\n      <li><strong>From</strong> کو وہ اکائی بنائیں جس میں عدد پہلے سے ہے، اور <strong>To</strong> کو وہ اکائی جو آپ چاہتے ہیں۔ سویپ بٹن (⇄) دونوں کو ایک ساتھ الٹ دیتا ہے۔</li>\n      <li>نمایاں نتیجہ پڑھیں، یا نیچے دیے گئے جدول تک اسکرول کریں جہاں وہی قدر ساتوں اکائیوں میں بیک وقت دکھائی جاتی ہے۔</li>\n    </ol>\n\n    <h3>حساب: hp ≠ PS کیوں</h3>\n    <p>یہاں ہر تبدیلی مشترکہ بنیاد کے طور پر واٹ (W) سے گزرتی ہے، اور ہر عامل کسی گول شدہ اندازے کے بجائے ایک درست تعریف سے آتا ہے۔ میکانکی ہارس پاور (hp) کی تعریف جیمز واٹ نے چکی چلانے والے گھوڑوں سے کی تھی، اور اسے بالکل <strong>550 فٹ پاؤنڈ کام فی سیکنڈ</strong> کے طور پر معیاری بنایا گیا — جو 745.6998715822702 W بنتا ہے۔ میٹرک ہارس پاور (PS، جرمن <em>Pferdestärke</em>، جسے cv یا hp(M) بھی لکھا جاتا ہے) کی تعریف اس کے بجائے <strong>75 کلوگرام قوت میٹر فی سیکنڈ</strong> ہے، معیاری کششِ ثقل (9.80665 m/s²) کے ساتھ، جو بالکل 735.49875 W بنتا ہے۔ چونکہ دونوں تعریفیں مختلف بنیادی اکائیوں سے شروع ہوتی ہیں (امپیریل فٹ پاؤنڈ بمقابلہ میٹرک کلوگرام قوت)، ان کے درمیان تقریباً 1.39% کا فرق آتا ہے — الجھانے کے لیے کافی قریب، اور اسپیک شیٹ پر اہم ہونے کے لیے کافی دور۔</p>\n\n    <h3>حل شدہ مثالیں</h3>\n    <div class=\"example\"><strong>1. یورپی اسپیک شیٹ کا امریکی سے موازنہ۔</strong> جرمنی میں \"150 PS\" درج ایک گاڑی: 150 × 735.49875 = 110,324.8 W ≈ <strong>110.32 kW</strong> ≈ <strong>147.95 hp</strong>۔ یعنی \"150 PS\" بالکل \"150 hp\" نہیں — یہ 148 hp سے کچھ کم ہے، اور مختلف اکائیوں میں بیان کردہ انجنوں کا موازنہ کرتے وقت یہ فرق جاننا ضروری ہے۔</div>\n    <div class=\"example\"><strong>2. کسی آلے کے لیے سرکٹ کا تعین۔</strong> 1.5 hp کا شاپ ویکیوم یا پول پمپ موٹر: 1.5 × 745.6998715822702 ≈ <strong>1,118.5 W</strong> (تقریباً 1.12 kW) درج شدہ میکانکی پیداوار۔ حقیقی برقی کھپت کچھ زیادہ ہوتی ہے کیونکہ موٹریں مکمل طور پر کارآمد نہیں ہوتیں — 15 A / 1,800 W کے گھریلو سرکٹ میں لگانے سے پہلے یہ جاننا مفید ہے۔</div>\n    <div class=\"example\"><strong>3. ایئر کنڈیشنر کی BTU/h درجہ بندی پڑھنا۔</strong> \"1 ٹن\" کا AC یونٹ 12,000 BTU/h پر درج ہوتا ہے: 12,000 × 0.29307107017222222 ≈ 3,516.85 W ≈ <strong>3.517 kW</strong>۔ یہی وہ عدد ہے جسے کسی یورپی یونٹ کی kW درجہ بندی یا جنریٹر کی پیداوار سے موازنہ کیا جاتا ہے۔</div>\n    <div class=\"example\"><strong>4. بیک اپ جنریٹر کا حجم طے کرنا۔</strong> 5 kW کا پورٹیبل جنریٹر، انجن کی تفصیل سے موازنے کے لیے ہارس پاور میں: 5,000 ÷ 745.6998715822702 ≈ <strong>6.71 hp</strong> مسلسل میکانکی پیداوار کے مساوی۔</div>\n\n    <h3>حوالہ: 1 W کے لحاظ سے درست تبدیلی عوامل</h3>\n    <table>\n      <thead><tr><th>اکائی</th><th>1 اکائی بواٹ</th><th>عام استعمال</th></tr></thead>\n      <tbody>\n        <tr><td>واٹ (W)</td><td>1 (بنیاد)</td><td>SI اکائی، الیکٹرانکس، چھوٹے آلات</td></tr>\n        <tr><td>کلوواٹ (kW)</td><td>1,000</td><td>موٹریں، جنریٹر، EV پاور ٹرین</td></tr>\n        <tr><td>میگاواٹ (MW)</td><td>1,000,000</td><td>بجلی گھر، صنعتی ٹربائن</td></tr>\n        <tr><td>ہارس پاور (hp)</td><td>745.6998715822702</td><td>امریکی/برطانوی انجن، پمپ، پاور ٹولز</td></tr>\n        <tr><td>میٹرک ہارس پاور (PS)</td><td>735.49875</td><td>یورپی یونین/جاپان/کوریا کی گاڑیوں کی تفصیلات</td></tr>\n        <tr><td>BTU فی گھنٹہ (BTU/h)</td><td>0.29307107017222222</td><td>ایئر کنڈیشنر، فرنس، HVAC</td></tr>\n        <tr><td>فٹ پاؤنڈ فی سیکنڈ (ft·lb/s)</td><td>1.3558179483314004</td><td>طبیعیات اور میکانیات کے مسائل</td></tr>\n      </tbody>\n    </table>\n\n    <h3>عام غلطیاں</h3>\n    <ul>\n      <li><strong>hp اور PS کو ایک ہی عدد سمجھنا۔</strong> یہ قریب ہیں (تقریباً 1.4% کا فرق) مگر \"300 PS\" کا انجن \"300 hp\" کا انجن نہیں — یہ 296 hp کے قریب ہے۔</li>\n      <li><strong>طاقت اور ٹارک کو خلط ملط کرنا۔</strong> انجن کی تفصیلات میں ٹارک (N·m یا lb-ft میں) بھی درج ہوتا ہے، جو ایک الگ طبیعی مقدار ہے — یہ ٹول صرف طاقت کی اکائیاں تبدیل کرتا ہے، ٹارک نہیں۔</li>\n      <li><strong>یہ سمجھنا کہ درج شدہ hp موٹر کی نیم پلیٹ کے برقی واٹ کے برابر ہے۔</strong> موٹر کی hp درجہ بندی میکانکی پیداوار بتاتی ہے؛ واٹ میں برقی ان پٹ کارکردگی کے نقصانات کی وجہ سے زیادہ ہوتا ہے، اس لیے سرکٹ بریکر کا حجم طے کرنے کے لیے صرف hp سے واٹ کی تبدیلی پر انحصار نہ کریں۔</li>\n      <li><strong>BTU (توانائی) اور BTU/h (طاقت) کو ملا دینا۔</strong> BTU/h ایک شرح ہے — یعنی طاقت — جبکہ سادہ BTU توانائی کی اکائی ہے، بالکل جیسے واٹ اور واٹ گھنٹہ آپس میں بدلے نہیں جا سکتے۔</li>\n    </ul>\n\n    <h3>یہ ٹول کیا نہیں کرتا</h3>\n    <p>یہ ایک اکائی تبدیل کرنے والا ٹول ہے، کارکردگی کا کیلکولیٹر نہیں — یہ آپ کے لکھے عدد کو اس کی ظاہری قیمت پر تبدیل کرتا ہے اور موٹر کی کارکردگی، ڈرائیو ٹرین کے نقصانات، یا انجن کی حقیقی بمقابلہ درج شدہ پیداوار کا حساب نہیں رکھ سکتا۔ برقی حفاظت کے کاموں (بریکر کا حجم، وائرنگ، جنریٹر کے بوجھ) کے لیے ہمیشہ آلے کی اصل نیم پلیٹ درجہ بندی استعمال کریں اور کسی مستند الیکٹریشن سے مشورہ کریں؛ یہ ٹول فوری موازنے کے لیے ہے، ضوابط کی تعمیل کے لیے نہیں۔</p>",
"id": "<style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:14px}\n      .guide-content th,.guide-content td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n    </style>\n\n    <h2>Mengapa hp, PS, dan kW tidak pernah benar-benar sejajar</h2>\n    <p>Angka daya berasal dari tiga tradisi berbeda yang semuanya masih muncul di lembar spesifikasi yang sama. Mesin mobil dipasarkan dalam horsepower (hp) di AS dan Inggris, dalam metric horsepower (PS) di sebagian besar Eropa, Jepang, dan Korea, serta makin sering dalam kilowatt (kW) karena persetujuan tipe UE dan spesifikasi kendaraan listrik mensyaratkannya. Peralatan rumah tangga dan pompa biasanya diberi peringkat dalam watt atau hp pada pelat namanya. AC dan tungku pemanas diberi peringkat dalam BTU/h. Tidak satu pun dari satuan ini menggambarkan besaran fisis yang berbeda — semuanya laju perpindahan energi — tetapi mengonversinya dari ingatan adalah sumber sebagian besar kesalahan lembar spesifikasi, terutama antara hp dan PS, yang tampak dapat dipertukarkan padahal tidak sepenuhnya.</p>\n\n    <h3>Cara menggunakannya</h3>\n    <ol>\n      <li>Masukkan angka yang Anda miliki — misalnya nilai hp pada spesifikasi mesin, atau daya watt pada label peralatan.</li>\n      <li>Atur <strong>From</strong> ke satuan asal angka tersebut, dan <strong>To</strong> ke satuan yang Anda inginkan. Tombol tukar (⇄) membalik keduanya sekaligus.</li>\n      <li>Baca hasil yang disorot, atau gulir ke tabel di bawah untuk melihat nilai yang sama dinyatakan dalam ketujuh satuan sekaligus.</li>\n    </ol>\n\n    <h3>Perhitungannya: mengapa hp ≠ PS</h3>\n    <p>Setiap konversi di sini melewati watt (W) sebagai basis bersama, dan setiap faktor berasal dari definisi eksak, bukan perkiraan yang dibulatkan. Horsepower mekanis (hp) didefinisikan oleh James Watt dari kuda yang memutar penggilingan, dan dibakukan tepat sebagai <strong>550 foot-pound kerja per detik</strong> — yang setara dengan 745.6998715822702 W. Metric horsepower (PS, bahasa Jerman <em>Pferdestärke</em>, ditulis juga cv atau hp(M)) justru didefinisikan sebagai <strong>75 kilogram-gaya-meter per detik</strong>, dengan gravitasi standar (9.80665 m/s²), yang tepat sama dengan 735.49875 W. Karena kedua definisi berangkat dari satuan dasar yang berbeda (foot-pound imperial vs. kilogram-gaya metrik), keduanya berselisih sekitar 1,39% — cukup dekat untuk membingungkan, cukup jauh untuk berarti di lembar spesifikasi.</p>\n\n    <h3>Contoh perhitungan</h3>\n    <div class=\"example\"><strong>1. Membandingkan lembar spesifikasi Eropa dengan AS.</strong> Mobil yang tertulis \"150 PS\" di Jerman: 150 × 735.49875 = 110.324,8 W ≈ <strong>110,32 kW</strong> ≈ <strong>147,95 hp</strong>. Jadi \"150 PS\" bukan persis \"150 hp\" — angkanya sedikit di bawah 148 hp, selisih yang patut diketahui saat membandingkan mesin yang dikutip dalam satuan berbeda.</div>\n    <div class=\"example\"><strong>2. Menentukan sirkuit untuk peralatan.</strong> Motor vakum bengkel atau pompa kolam 1,5 hp: 1,5 × 745.6998715822702 ≈ <strong>1.118,5 W</strong> (sekitar 1,12 kW) keluaran mekanis terukur. Konsumsi listrik nyatanya sedikit lebih tinggi karena motor tidak sepenuhnya efisien — berguna diketahui sebelum mencolokkannya ke sirkuit rumah 15 A / 1.800 W.</div>\n    <div class=\"example\"><strong>3. Membaca peringkat BTU/h pada AC.</strong> Unit AC \"1 ton\" diberi peringkat 12.000 BTU/h: 12.000 × 0.29307107017222222 ≈ 3.516,85 W ≈ <strong>3,517 kW</strong>. Itulah angka pembanding terhadap peringkat kW unit Eropa atau keluaran generator.</div>\n    <div class=\"example\"><strong>4. Menentukan ukuran generator cadangan.</strong> Generator portabel 5 kW, dinyatakan dalam horsepower untuk membandingkan spesifikasi mesin: 5.000 ÷ 745.6998715822702 ≈ <strong>6,71 hp</strong> setara keluaran mekanis kontinu.</div>\n\n    <h3>Referensi: faktor konversi eksak ke 1 W</h3>\n    <table>\n      <thead><tr><th>Satuan</th><th>1 satuan dalam W</th><th>Penggunaan umum</th></tr></thead>\n      <tbody>\n        <tr><td>Watt (W)</td><td>1 (basis)</td><td>Satuan SI, elektronik, peralatan kecil</td></tr>\n        <tr><td>Kilowatt (kW)</td><td>1.000</td><td>Motor, generator, powertrain EV</td></tr>\n        <tr><td>Megawatt (MW)</td><td>1.000.000</td><td>Pembangkit listrik, turbin industri</td></tr>\n        <tr><td>Horsepower (hp)</td><td>745.6998715822702</td><td>Mesin AS/Inggris, pompa, perkakas listrik</td></tr>\n        <tr><td>Metric horsepower (PS)</td><td>735.49875</td><td>Spesifikasi mobil UE/Jepang/Korea</td></tr>\n        <tr><td>BTU per jam (BTU/h)</td><td>0.29307107017222222</td><td>AC, tungku pemanas, HVAC</td></tr>\n        <tr><td>Foot-pound per detik (ft·lb/s)</td><td>1.3558179483314004</td><td>Soal fisika dan mekanika</td></tr>\n      </tbody>\n    </table>\n\n    <h3>Kesalahan umum</h3>\n    <ul>\n      <li><strong>Menganggap hp dan PS angka yang sama.</strong> Keduanya berdekatan (selisih sekitar 1,4%), tetapi mesin \"300 PS\" bukan mesin \"300 hp\" — lebih dekat ke 296 hp.</li>\n      <li><strong>Mengacaukan daya dengan torsi.</strong> Spesifikasi mesin juga mencantumkan torsi (dalam N·m atau lb-ft), besaran fisis yang berbeda — alat ini hanya mengonversi satuan daya, bukan torsi.</li>\n      <li><strong>Mengira hp terukur sama dengan watt listrik pada pelat nama motor.</strong> Peringkat hp motor menyatakan keluaran mekanis; masukan listrik dalam watt lebih tinggi karena kerugian efisiensi, jadi jangan gunakan konversi hp-ke-watt saja untuk menentukan ukuran pemutus sirkuit.</li>\n      <li><strong>Mencampuradukkan BTU (energi) dengan BTU/h (daya).</strong> BTU/h adalah laju — yaitu daya — sedangkan BTU biasa adalah satuan energi, sebagaimana watt dan watt-jam tidak dapat dipertukarkan.</li>\n    </ul>\n\n    <h3>Yang tidak dilakukan alat ini</h3>\n    <p>Ini adalah pengonversi satuan, bukan kalkulator efisiensi — alat ini mengonversi angka yang Anda ketik apa adanya dan tidak dapat memperhitungkan efisiensi motor, kerugian drivetrain, atau keluaran nyata mesin dibanding angka terukurnya. Untuk pekerjaan keselamatan listrik (penentuan pemutus, pengabelan, beban generator), selalu gunakan peringkat pelat nama peralatan yang sebenarnya dan konsultasikan dengan teknisi listrik bersertifikat; alat ini untuk perbandingan cepat, bukan untuk kepatuhan standar.</p>",
"bn": "<style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:14px}\n      .guide-content th,.guide-content td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n    </style>\n\n    <h2>hp, PS আর kW কেন কখনোই ঠিক মেলে না</h2>\n    <p>পাওয়ার রেটিং তিনটি আলাদা ঐতিহ্য থেকে এসেছে, আর তিনটিই আজও একই স্পেক শিটে দেখা যায়। গাড়ির ইঞ্জিন যুক্তরাষ্ট্র ও যুক্তরাজ্যে হর্সপাওয়ারে (hp), ইউরোপের বেশির ভাগ অংশ, জাপান ও কোরিয়ায় মেট্রিক হর্সপাওয়ারে (PS), এবং ক্রমবর্ধমানভাবে কিলোওয়াটে (kW) বিপণন করা হয়, কারণ EU টাইপ-অনুমোদন ও বৈদ্যুতিক গাড়ির স্পেক তা দাবি করে। গৃহস্থালি যন্ত্র ও পাম্পের নেমপ্লেটে সাধারণত ওয়াট বা hp লেখা থাকে। এয়ার কন্ডিশনার ও ফার্নেস রেট করা হয় BTU/h-এ। এগুলোর কোনোটিই আলাদা ভৌত রাশি বোঝায় না — সবই শক্তি স্থানান্তরের হার — কিন্তু স্মৃতির ভরসায় এদের রূপান্তর করাই স্পেক-শিটের বেশির ভাগ ভুলের উৎস, বিশেষত hp ও PS-এর মধ্যে, যা দেখতে বিনিময়যোগ্য মনে হলেও ঠিক তা নয়।</p>\n\n    <h3>কীভাবে ব্যবহার করবেন</h3>\n    <ol>\n      <li>আপনার হাতে থাকা সংখ্যাটি লিখুন — যেমন ইঞ্জিন স্পেকের hp মান, বা যন্ত্রের লেবেলে লেখা ওয়াট।</li>\n      <li><strong>From</strong>-এ সেই একক দিন যেটিতে সংখ্যাটি ইতিমধ্যেই আছে, আর <strong>To</strong>-এ যেটি আপনি চান। সোয়াপ বোতাম (⇄) দুটিকে একসাথে উল্টে দেয়।</li>\n      <li>হাইলাইট করা ফলাফল পড়ুন, অথবা নিচের টেবিলে স্ক্রল করে একই মান একসাথে সাতটি এককেই দেখে নিন।</li>\n    </ol>\n\n    <h3>হিসাব: hp ≠ PS কেন</h3>\n    <p>এখানে প্রতিটি রূপান্তর সাধারণ ভিত্তি হিসেবে ওয়াট (W)-এর মধ্য দিয়ে যায়, আর প্রতিটি গুণক আসে গোল করা আন্দাজ নয়, সুনির্দিষ্ট সংজ্ঞা থেকে। যান্ত্রিক হর্সপাওয়ার (hp) সংজ্ঞায়িত করেছিলেন জেমস ওয়াট, কল ঘোরানো ঘোড়া থেকে, এবং তা ঠিক <strong>প্রতি সেকেন্ডে 550 ফুট-পাউন্ড কাজ</strong> হিসেবে মানসম্মত করা হয় — যা দাঁড়ায় 745.6998715822702 W। মেট্রিক হর্সপাওয়ার (PS, জার্মান <em>Pferdestärke</em>, cv বা hp(M) নামেও লেখা হয়) সংজ্ঞায়িত হয় বরং <strong>প্রতি সেকেন্ডে 75 কিলোগ্রাম-বল-মিটার</strong> হিসেবে, আদর্শ অভিকর্ষ (9.80665 m/s²) ব্যবহার করে, যা ঠিক 735.49875 W। যেহেতু দুটি সংজ্ঞা ভিন্ন মৌল একক থেকে শুরু হয় (ইম্পেরিয়াল ফুট-পাউন্ড বনাম মেট্রিক কিলোগ্রাম-বল), এদের ব্যবধান প্রায় 1.39% — বিভ্রান্ত করার মতো কাছাকাছি, আবার স্পেক শিটে গুরুত্বপূর্ণ হওয়ার মতো দূরে।</p>\n\n    <h3>উদাহরণসহ হিসাব</h3>\n    <div class=\"example\"><strong>১. ইউরোপীয় স্পেক শিটের সঙ্গে মার্কিন স্পেকের তুলনা।</strong> জার্মানিতে \"150 PS\" বলা একটি গাড়ি: 150 × 735.49875 = 110,324.8 W ≈ <strong>110.32 kW</strong> ≈ <strong>147.95 hp</strong>। অর্থাৎ \"150 PS\" ঠিক \"150 hp\" নয় — এটি 148 hp-এর সামান্য নিচে, ভিন্ন এককে বলা ইঞ্জিন তুলনার সময় এই ব্যবধান জানা দরকার।</div>\n    <div class=\"example\"><strong>২. যন্ত্রের জন্য সার্কিট নির্ধারণ।</strong> 1.5 hp শপ ভ্যাকুয়াম বা পুল পাম্প মোটর: 1.5 × 745.6998715822702 ≈ <strong>1,118.5 W</strong> (প্রায় 1.12 kW) রেটেড যান্ত্রিক আউটপুট। প্রকৃত বৈদ্যুতিক টান কিছুটা বেশি হয়, কারণ মোটর পুরোপুরি দক্ষ নয় — 15 A / 1,800 W গৃহস্থালি সার্কিটে লাগানোর আগে এটি জানা কাজে দেয়।</div>\n    <div class=\"example\"><strong>৩. এয়ার কন্ডিশনারের BTU/h রেটিং পড়া।</strong> \"1-টন\" AC ইউনিট রেট করা হয় 12,000 BTU/h-এ: 12,000 × 0.29307107017222222 ≈ 3,516.85 W ≈ <strong>3.517 kW</strong>। ইউরোপীয় ইউনিটের kW রেটিং বা জেনারেটরের আউটপুটের সঙ্গে তুলনার জন্য এটিই সেই সংখ্যা।</div>\n    <div class=\"example\"><strong>৪. ব্যাকআপ জেনারেটরের মাপ ঠিক করা।</strong> 5 kW পোর্টেবল জেনারেটর, ইঞ্জিন স্পেক তুলনার জন্য হর্সপাওয়ারে: 5,000 ÷ 745.6998715822702 ≈ <strong>6.71 hp</strong> ধারাবাহিক যান্ত্রিক আউটপুটের সমতুল্য।</div>\n\n    <h3>রেফারেন্স: 1 W-এ সুনির্দিষ্ট রূপান্তর গুণক</h3>\n    <table>\n      <thead><tr><th>একক</th><th>1 একক W-এ</th><th>সাধারণ ব্যবহার</th></tr></thead>\n      <tbody>\n        <tr><td>ওয়াট (W)</td><td>1 (ভিত্তি)</td><td>SI একক, ইলেকট্রনিক্স, ছোট যন্ত্র</td></tr>\n        <tr><td>কিলোওয়াট (kW)</td><td>1,000</td><td>মোটর, জেনারেটর, EV পাওয়ারট্রেন</td></tr>\n        <tr><td>মেগাওয়াট (MW)</td><td>1,000,000</td><td>বিদ্যুৎকেন্দ্র, শিল্প টারবাইন</td></tr>\n        <tr><td>হর্সপাওয়ার (hp)</td><td>745.6998715822702</td><td>US/UK ইঞ্জিন, পাম্প, পাওয়ার টুল</td></tr>\n        <tr><td>মেট্রিক হর্সপাওয়ার (PS)</td><td>735.49875</td><td>EU/জাপান/কোরিয়ার গাড়ির স্পেক</td></tr>\n        <tr><td>প্রতি ঘণ্টায় BTU (BTU/h)</td><td>0.29307107017222222</td><td>এয়ার কন্ডিশনার, ফার্নেস, HVAC</td></tr>\n        <tr><td>প্রতি সেকেন্ডে ফুট-পাউন্ড (ft·lb/s)</td><td>1.3558179483314004</td><td>পদার্থবিদ্যা ও বলবিদ্যার সমস্যা</td></tr>\n      </tbody>\n    </table>\n\n    <h3>সাধারণ ভুল</h3>\n    <ul>\n      <li><strong>hp আর PS-কে একই সংখ্যা ভাবা।</strong> এরা কাছাকাছি (প্রায় 1.4% ব্যবধান) কিন্তু \"300 PS\" ইঞ্জিন \"300 hp\" ইঞ্জিন নয় — এটি 296 hp-এর কাছাকাছি।</li>\n      <li><strong>পাওয়ার আর টর্ক গুলিয়ে ফেলা।</strong> ইঞ্জিন স্পেকে টর্কও (N·m বা lb-ft-এ) থাকে, যা আলাদা ভৌত রাশি — এই টুল শুধু পাওয়ার একক রূপান্তর করে, টর্ক নয়।</li>\n      <li><strong>রেটেড hp-কে মোটরের নেমপ্লেটের বৈদ্যুতিক ওয়াটের সমান ধরা।</strong> মোটরের hp রেটিং যান্ত্রিক আউটপুট বোঝায়; ওয়াটে বৈদ্যুতিক ইনপুট দক্ষতাজনিত ক্ষতির কারণে বেশি হয়, তাই সার্কিট ব্রেকারের মাপ ঠিক করতে শুধু hp-থেকে-ওয়াট রূপান্তরের ওপর ভরসা করবেন না।</li>\n      <li><strong>BTU (শক্তি) আর BTU/h (পাওয়ার) মিলিয়ে ফেলা।</strong> BTU/h একটি হার — অর্থাৎ পাওয়ার — আর সাধারণ BTU শক্তির একক, ঠিক যেমন ওয়াট আর ওয়াট-ঘণ্টা বিনিময়যোগ্য নয়।</li>\n    </ul>\n\n    <h3>এই টুল যা করে না</h3>\n    <p>এটি একটি একক রূপান্তরকারী, দক্ষতা ক্যালকুলেটর নয় — আপনি যে সংখ্যা লিখবেন তা মুখ্য মান ধরে রূপান্তর করে, মোটরের দক্ষতা, ড্রাইভট্রেন ক্ষতি বা ইঞ্জিনের প্রকৃত বনাম রেটেড আউটপুট হিসাব করতে পারে না। বৈদ্যুতিক নিরাপত্তার কাজে (ব্রেকার নির্ধারণ, ওয়্যারিং, জেনারেটর লোড) সবসময় সরঞ্জামের প্রকৃত নেমপ্লেট রেটিং ব্যবহার করুন ও যোগ্য ইলেকট্রিশিয়ানের পরামর্শ নিন; এই টুল দ্রুত তুলনার জন্য, কোড মেনে চলার জন্য নয়।</p>",
"hi": "<style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:14px}\n      .guide-content th,.guide-content td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n    </style>\n\n    <h2>hp, PS और kW कभी पूरी तरह मेल क्यों नहीं खाते</h2>\n    <p>पावर रेटिंग तीन अलग-अलग परंपराओं से आती हैं, और तीनों आज भी एक ही स्पेक शीट पर दिख जाती हैं। कार इंजन अमेरिका और ब्रिटेन में हॉर्सपावर (hp) में, अधिकांश यूरोप, जापान और कोरिया में मीट्रिक हॉर्सपावर (PS) में, और बढ़ते हुए किलोवाट (kW) में बताए जाते हैं, क्योंकि EU टाइप-अप्रूवल और इलेक्ट्रिक वाहन स्पेक इसकी माँग करते हैं। घरेलू उपकरण और पंप आमतौर पर नेमप्लेट पर वाट या hp में रेट किए जाते हैं। एयर कंडीशनर और फर्नेस BTU/h में रेट होते हैं। इनमें से कोई भी अलग भौतिक राशि नहीं बताता — ये सब ऊर्जा स्थानांतरण की दरें हैं — पर इन्हें याद के भरोसे बदलना ही अधिकांश स्पेक-शीट गलतियों की जड़ है, खासकर hp और PS के बीच, जो देखने में एक जैसे लगते हैं पर पूरी तरह एक नहीं हैं।</p>\n\n    <h3>इसका उपयोग कैसे करें</h3>\n    <ol>\n      <li>अपना संख्या मान दर्ज करें — जैसे इंजन स्पेक का hp आँकड़ा, या उपकरण के लेबल पर लिखी वाट संख्या।</li>\n      <li><strong>From</strong> में वह इकाई चुनें जिसमें संख्या पहले से है, और <strong>To</strong> में वह इकाई जो आपको चाहिए। स्वैप बटन (⇄) दोनों को एक साथ पलट देता है।</li>\n      <li>हाइलाइट किया गया परिणाम पढ़ें, या नीचे दी गई तालिका देखें जिसमें वही मान सातों इकाइयों में एक साथ दिखता है।</li>\n    </ol>\n\n    <h3>गणित: hp ≠ PS क्यों</h3>\n    <p>यहाँ हर रूपांतरण साझा आधार के रूप में वाट (W) से होकर गुजरता है, और हर गुणांक किसी गोल किए अनुमान से नहीं बल्कि सटीक परिभाषा से आता है। यांत्रिक हॉर्सपावर (hp) को जेम्स वाट ने चक्की चलाते घोड़ों से परिभाषित किया था, और इसे ठीक <strong>550 फुट-पाउंड कार्य प्रति सेकंड</strong> के रूप में मानकीकृत किया गया — यानी 745.6998715822702 W। मीट्रिक हॉर्सपावर (PS, जर्मन <em>Pferdestärke</em>, जिसे cv या hp(M) भी लिखा जाता है) की परिभाषा इसके बजाय <strong>75 किलोग्राम-बल-मीटर प्रति सेकंड</strong> है, मानक गुरुत्व (9.80665 m/s²) के साथ, जो ठीक 735.49875 W बनता है। चूँकि दोनों परिभाषाएँ अलग आधार इकाइयों से शुरू होती हैं (इंपीरियल फुट-पाउंड बनाम मीट्रिक किलोग्राम-बल), वे लगभग 1.39% अलग पड़ती हैं — भ्रमित करने जितनी नज़दीक, और स्पेक शीट पर मायने रखने जितनी दूर।</p>\n\n    <h3>हल किए गए उदाहरण</h3>\n    <div class=\"example\"><strong>1. यूरोपीय स्पेक शीट की अमेरिकी से तुलना।</strong> जर्मनी में \"150 PS\" बताई गई कार: 150 × 735.49875 = 110,324.8 W ≈ <strong>110.32 kW</strong> ≈ <strong>147.95 hp</strong>। यानी \"150 PS\" ठीक \"150 hp\" नहीं है — यह 148 hp से थोड़ा कम है, और अलग इकाइयों में बताए इंजनों की तुलना करते समय यह अंतर जानना ज़रूरी है।</div>\n    <div class=\"example\"><strong>2. उपकरण के लिए सर्किट का आकार तय करना।</strong> 1.5 hp का शॉप वैक्यूम या पूल पंप मोटर: 1.5 × 745.6998715822702 ≈ <strong>1,118.5 W</strong> (लगभग 1.12 kW) रेटेड यांत्रिक आउटपुट। वास्तविक विद्युत खपत कुछ अधिक होती है क्योंकि मोटरें पूरी तरह दक्ष नहीं होतीं — 15 A / 1,800 W घरेलू सर्किट में लगाने से पहले यह जानना उपयोगी है।</div>\n    <div class=\"example\"><strong>3. एयर कंडीशनर की BTU/h रेटिंग पढ़ना।</strong> \"1-टन\" AC यूनिट 12,000 BTU/h पर रेट होती है: 12,000 × 0.29307107017222222 ≈ 3,516.85 W ≈ <strong>3.517 kW</strong>। यही आँकड़ा किसी यूरोपीय यूनिट की kW रेटिंग या जनरेटर के आउटपुट से तुलना के लिए काम आता है।</div>\n    <div class=\"example\"><strong>4. बैकअप जनरेटर का आकार तय करना।</strong> 5 kW का पोर्टेबल जनरेटर, इंजन स्पेक तुलना के लिए हॉर्सपावर में: 5,000 ÷ 745.6998715822702 ≈ <strong>6.71 hp</strong> के सतत यांत्रिक आउटपुट के समतुल्य।</div>\n\n    <h3>संदर्भ: 1 W में सटीक रूपांतरण गुणांक</h3>\n    <table>\n      <thead><tr><th>इकाई</th><th>1 इकाई W में</th><th>सामान्य उपयोग</th></tr></thead>\n      <tbody>\n        <tr><td>वाट (W)</td><td>1 (आधार)</td><td>SI इकाई, इलेक्ट्रॉनिक्स, छोटे उपकरण</td></tr>\n        <tr><td>किलोवाट (kW)</td><td>1,000</td><td>मोटर, जनरेटर, EV पावरट्रेन</td></tr>\n        <tr><td>मेगावाट (MW)</td><td>1,000,000</td><td>बिजली संयंत्र, औद्योगिक टर्बाइन</td></tr>\n        <tr><td>हॉर्सपावर (hp)</td><td>745.6998715822702</td><td>US/UK इंजन, पंप, पावर टूल</td></tr>\n        <tr><td>मीट्रिक हॉर्सपावर (PS)</td><td>735.49875</td><td>EU/जापान/कोरिया कार स्पेक</td></tr>\n        <tr><td>BTU प्रति घंटा (BTU/h)</td><td>0.29307107017222222</td><td>एयर कंडीशनर, फर्नेस, HVAC</td></tr>\n        <tr><td>फुट-पाउंड प्रति सेकंड (ft·lb/s)</td><td>1.3558179483314004</td><td>भौतिकी और यांत्रिकी की समस्याएँ</td></tr>\n      </tbody>\n    </table>\n\n    <h3>आम गलतियाँ</h3>\n    <ul>\n      <li><strong>hp और PS को एक ही संख्या मान लेना।</strong> ये करीब हैं (लगभग 1.4% का अंतर) पर \"300 PS\" इंजन \"300 hp\" इंजन नहीं है — यह 296 hp के करीब है।</li>\n      <li><strong>पावर और टॉर्क को गड्डमड्ड करना।</strong> इंजन स्पेक में टॉर्क (N·m या lb-ft में) भी होता है, जो अलग भौतिक राशि है — यह टूल केवल पावर इकाइयाँ बदलता है, टॉर्क नहीं।</li>\n      <li><strong>यह मान लेना कि रेटेड hp मोटर नेमप्लेट के विद्युत वाट के बराबर है।</strong> मोटर की hp रेटिंग यांत्रिक आउटपुट बताती है; वाट में विद्युत इनपुट दक्षता हानि के कारण अधिक होता है, इसलिए सर्किट ब्रेकर चुनने के लिए अकेले hp-से-वाट रूपांतरण पर निर्भर न रहें।</li>\n      <li><strong>BTU (ऊर्जा) और BTU/h (पावर) को मिला देना।</strong> BTU/h एक दर है — यानी पावर — जबकि सादा BTU ऊर्जा की इकाई है, ठीक वैसे ही जैसे वाट और वाट-घंटा आपस में बदले नहीं जा सकते।</li>\n    </ul>\n\n    <h3>यह टूल क्या नहीं करता</h3>\n    <p>यह एक यूनिट कन्वर्टर है, दक्षता कैलकुलेटर नहीं — यह आपकी दी गई संख्या को उसके अंकित मान पर बदलता है और मोटर दक्षता, ड्राइवट्रेन हानि या इंजन के वास्तविक बनाम रेटेड आउटपुट का हिसाब नहीं रख सकता। विद्युत सुरक्षा से जुड़े काम (ब्रेकर साइज़िंग, वायरिंग, जनरेटर लोड) के लिए हमेशा उपकरण की वास्तविक नेमप्लेट रेटिंग का उपयोग करें और योग्य इलेक्ट्रीशियन से सलाह लें; यह टूल त्वरित तुलना के लिए है, कोड अनुपालन के लिए नहीं।</p>",
"ar": "<style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:14px}\n      .guide-content th,.guide-content td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n    </style>\n\n    <h2>لماذا لا تتطابق hp و PS و kW تمامًا</h2>\n    <p>تأتي تصنيفات القدرة من ثلاثة تقاليد مختلفة ما زالت تظهر جميعها في ورقة المواصفات نفسها. تُسوَّق محركات السيارات بالحصان (hp) في الولايات المتحدة والمملكة المتحدة، وبالحصان المتري (PS) في معظم أوروبا واليابان وكوريا، وبالكيلوواط (kW) بشكل متزايد لأن اعتماد النوع في الاتحاد الأوروبي ومواصفات السيارات الكهربائية تتطلب ذلك. أما الأجهزة المنزلية والمضخات فتُصنَّف عادة بالواط أو بالحصان على لوحة البيانات. وتُصنَّف المكيفات وأفران التدفئة بوحدة BTU/h. لا تصف أي من هذه الوحدات كميات فيزيائية مختلفة — فكلها معدلات لنقل الطاقة — لكن التحويل بينها من الذاكرة هو مصدر معظم الأخطاء في أوراق المواصفات، خصوصًا بين hp و PS اللتين تبدوان متكافئتين وهما ليستا كذلك تمامًا.</p>\n\n    <h3>طريقة الاستخدام</h3>\n    <ol>\n      <li>أدخل الرقم الذي لديك — مثل قيمة hp في مواصفات المحرك، أو عدد الواط على ملصق الجهاز.</li>\n      <li>اضبط <strong>من</strong> على الوحدة التي يوجد بها الرقم أصلًا، و<strong>إلى</strong> على الوحدة التي تريدها. زر التبديل (⇄) يعكس الاثنين دفعة واحدة.</li>\n      <li>اقرأ النتيجة المميزة، أو مرّر إلى الجدول أدناه لرؤية القيمة نفسها معبَّرًا عنها بجميع الوحدات السبع في الوقت ذاته.</li>\n    </ol>\n\n    <h3>الحساب: لماذا hp ≠ PS</h3>\n    <p>كل تحويل هنا يمر عبر الواط (W) كأساس مشترك، وكل معامل مأخوذ من تعريف دقيق لا من تقدير مقرَّب. عُرِّف الحصان الميكانيكي (hp) على يد جيمس واط انطلاقًا من خيول تدير طاحونة، وجرى توحيده ليساوي بالضبط <strong>550 قدم-رطل من الشغل في الثانية</strong> — أي 745.6998715822702 واط. أما الحصان المتري (PS، بالألمانية <em>Pferdestärke</em>، ويُكتب أيضًا cv أو hp(M)) فيُعرَّف بأنه <strong>75 كيلوغرام-قوة-متر في الثانية</strong>، باستخدام الجاذبية القياسية (9.80665 م/ث²)، وهو ما يساوي بالضبط 735.49875 واط. ولأن التعريفين ينطلقان من وحدات أساس مختلفة (القدم-رطل الإمبراطوري مقابل الكيلوغرام-قوة المتري)، فإن الفارق بينهما نحو 1.39% — قريب بما يكفي ليُربك، وبعيد بما يكفي ليكون مهمًا في ورقة المواصفات.</p>\n\n    <h3>أمثلة محلولة</h3>\n    <div class=\"example\"><strong>1. مقارنة ورقة مواصفات أوروبية بأخرى أمريكية.</strong> سيارة مُدرجة بـ «150 PS» في ألمانيا: 150 × 735.49875 = 110,324.8 واط ≈ <strong>110.32 kW</strong> ≈ <strong>147.95 hp</strong>. إذن «150 PS» ليست «150 hp» تمامًا — بل أقل قليلًا من 148 hp، وهو فارق يستحق المعرفة عند المقارنة بين محركات مذكورة بوحدات مختلفة.</div>\n    <div class=\"example\"><strong>2. تحديد دائرة كهربائية لجهاز.</strong> مكنسة ورشة أو مضخة مسبح بقدرة 1.5 hp: 1.5 × 745.6998715822702 ≈ <strong>1,118.5 واط</strong> (نحو 1.12 kW) من الخرج الميكانيكي المقنن. السحب الكهربائي الفعلي أعلى قليلًا لأن المحركات ليست مثالية الكفاءة — وهي معلومة مفيدة قبل التوصيل بدائرة منزلية 15 A / 1,800 W.</div>\n    <div class=\"example\"><strong>3. قراءة تصنيف BTU/h لمكيف الهواء.</strong> وحدة تكييف «طن واحد» مصنَّفة عند 12,000 BTU/h: 12,000 × 0.29307107017222222 ≈ 3,516.85 واط ≈ <strong>3.517 kW</strong>. هذا هو الرقم الذي تقارنه بتصنيف kW لوحدة أوروبية أو بخرج مولّد.</div>\n    <div class=\"example\"><strong>4. تحديد حجم مولّد احتياطي.</strong> مولّد محمول بقدرة 5 kW، معبَّرًا عنه بالحصان لمقارنته بمواصفات محرك: 5,000 ÷ 745.6998715822702 ≈ <strong>6.71 hp</strong> من مكافئ الخرج الميكانيكي المستمر.</div>\n\n    <h3>مرجع: معاملات التحويل الدقيقة إلى 1 W</h3>\n    <table>\n      <thead><tr><th>الوحدة</th><th>1 وحدة بالواط</th><th>الاستخدام المعتاد</th></tr></thead>\n      <tbody>\n        <tr><td>واط (W)</td><td>1 (الأساس)</td><td>وحدة SI، الإلكترونيات، الأجهزة الصغيرة</td></tr>\n        <tr><td>كيلوواط (kW)</td><td>1,000</td><td>المحركات، المولّدات، أنظمة الدفع الكهربائية</td></tr>\n        <tr><td>ميغاواط (MW)</td><td>1,000,000</td><td>محطات الطاقة، التوربينات الصناعية</td></tr>\n        <tr><td>حصان (hp)</td><td>745.6998715822702</td><td>محركات الولايات المتحدة/بريطانيا، المضخات، العدد الكهربائية</td></tr>\n        <tr><td>حصان متري (PS)</td><td>735.49875</td><td>مواصفات سيارات الاتحاد الأوروبي/اليابان/كوريا</td></tr>\n        <tr><td>وحدة حرارية بريطانية في الساعة (BTU/h)</td><td>0.29307107017222222</td><td>المكيفات، الأفران، التدفئة والتهوية</td></tr>\n        <tr><td>قدم-رطل في الثانية (ft·lb/s)</td><td>1.3558179483314004</td><td>مسائل الفيزياء والميكانيكا</td></tr>\n      </tbody>\n    </table>\n\n    <h3>أخطاء شائعة</h3>\n    <ul>\n      <li><strong>اعتبار hp و PS الرقم نفسه.</strong> هما متقاربتان (بفارق نحو 1.4%) لكن محرك «300 PS» ليس محرك «300 hp» — بل أقرب إلى 296 hp.</li>\n      <li><strong>الخلط بين القدرة وعزم الدوران.</strong> تذكر مواصفات المحرك أيضًا عزم الدوران (بوحدة N·m أو lb-ft)، وهو كمية فيزيائية مختلفة — هذه الأداة تحوّل وحدات القدرة فقط، لا العزم.</li>\n      <li><strong>افتراض أن الحصان المقنن يساوي الواط الكهربائي على لوحة بيانات المحرك.</strong> تصنيف hp للمحرك يصف الخرج الميكانيكي؛ أما الدخل الكهربائي بالواط فهو أعلى بسبب خسائر الكفاءة، لذا لا تعتمد على تحويل hp إلى واط وحده لتحديد قاطع الدائرة.</li>\n      <li><strong>الخلط بين BTU (طاقة) و BTU/h (قدرة).</strong> إن BTU/h معدل — أي قدرة — بينما BTU المجردة وحدة طاقة، تمامًا كما أن الواط والواط-ساعة ليسا متكافئين.</li>\n    </ul>\n\n    <h3>ما لا تفعله هذه الأداة</h3>\n    <p>هذه أداة تحويل وحدات وليست حاسبة كفاءة — فهي تحوّل الرقم الذي تكتبه بقيمته الظاهرة ولا يمكنها مراعاة كفاءة المحرك أو خسائر نقل الحركة أو الفرق بين الخرج الفعلي للمحرك وقيمته المقننة. وللأعمال المتعلقة بالسلامة الكهربائية (تحديد القواطع، الأسلاك، أحمال المولّدات)، استخدم دائمًا التصنيفات الفعلية على لوحة بيانات الجهاز واستشر كهربائيًا مؤهلًا؛ هذه الأداة للمقارنات السريعة، لا للامتثال للأكواد.</p>",
"ru": "<style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:14px}\n      .guide-content th,.guide-content td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n    </style>\n    <h2>Почему hp, л.с. и кВт никогда не совпадают в точности</h2>\n    <p>Значения мощности пришли из трёх разных традиций, и все три до сих пор встречаются в одной и той же спецификации. Автомобильные двигатели в США и Великобритании рекламируют в механических лошадиных силах (hp), в большей части Европы, в Японии и Корее — в метрических лошадиных силах (PS, л.с.), и всё чаще в киловаттах (кВт), поскольку этого требуют европейская сертификация типа и спецификации электромобилей. На бытовой технике и насосах на шильдике обычно указывают ватты или hp. Кондиционеры и котлы маркируют в BTU/ч. Ни одна из этих единиц не описывает иную физическую величину — все они выражают скорость передачи энергии, — но именно пересчёт по памяти порождает большинство ошибок при чтении спецификаций, особенно между hp и PS, которые выглядят взаимозаменяемыми, но таковыми не являются.</p>\n\n    <h3>Как пользоваться</h3>\n    <ol>\n      <li>Введите имеющееся число — например, значение в hp из спецификации двигателя или мощность в ваттах с этикетки прибора.</li>\n      <li>Установите поле <strong>Из</strong> на единицу, в которой число уже выражено, а поле <strong>В</strong> — на нужную единицу. Кнопка обмена (⇄) меняет их местами одним нажатием.</li>\n      <li>Прочитайте выделенный результат или прокрутите таблицу ниже, чтобы увидеть то же значение сразу во всех семи единицах.</li>\n    </ol>\n\n    <h3>Математика: почему hp ≠ PS</h3>\n    <p>Все пересчёты здесь идут через ватт (Вт) как общую основу, и каждый коэффициент взят из точного определения, а не из округлённой оценки. Механическая лошадиная сила (hp) была введена Джеймсом Уаттом по работе лошадей на мельнице и стандартизирована как ровно <strong>550 фут-фунтов работы в секунду</strong> — это даёт 745,6998715822702 Вт. Метрическая лошадиная сила (PS, нем. <em>Pferdestärke</em>, также пишется cv или hp(M)) определена иначе — как <strong>75 килограмм-сила-метров в секунду</strong> при стандартном ускорении свободного падения (9,80665 м/с²), что составляет ровно 735,49875 Вт. Поскольку два определения исходят из разных базовых единиц (имперские фут-фунты против метрической килограмм-силы), они расходятся примерно на 1,39 % — достаточно близко, чтобы запутать, и достаточно далеко, чтобы это имело значение в спецификации.</p>\n\n    <h3>Разобранные примеры</h3>\n    <div class=\"example\"><strong>1. Сравнение европейской спецификации с американской.</strong> Автомобиль, заявленный в Германии как «150 PS»: 150 × 735,49875 = 110 324,8 Вт ≈ <strong>110,32 кВт</strong> ≈ <strong>147,95 hp</strong>. То есть «150 PS» — это не совсем «150 hp», а чуть меньше 148 hp; разницу стоит учитывать при сравнении двигателей, заявленных в разных единицах.</div>\n    <div class=\"example\"><strong>2. Расчёт линии питания для прибора.</strong> Строительный пылесос или мотор насоса бассейна на 1,5 hp: 1,5 × 745,6998715822702 ≈ <strong>1118,5 Вт</strong> (около 1,12 кВт) номинальной механической мощности. Реальное потребление электроэнергии несколько выше, поскольку двигатели не идеально эффективны — полезно знать перед подключением к бытовой линии 15 А / 1800 Вт.</div>\n    <div class=\"example\"><strong>3. Чтение маркировки кондиционера в BTU/ч.</strong> Кондиционер «на 1 тонну» имеет мощность 12 000 BTU/ч: 12 000 × 0,29307107017222222 ≈ 3516,85 Вт ≈ <strong>3,517 кВт</strong>. Именно это значение сравнивают с мощностью европейской модели в кВт или с выходом генератора.</div>\n    <div class=\"example\"><strong>4. Подбор резервного генератора.</strong> Переносной генератор на 5 кВт, выраженный в лошадиных силах для сравнения со спецификацией двигателя: 5000 ÷ 745,6998715822702 ≈ <strong>6,71 hp</strong> эквивалентной длительной механической мощности.</div>\n\n    <h3>Справка: точные коэффициенты пересчёта в 1 Вт</h3>\n    <table>\n      <thead><tr><th>Единица</th><th>1 единица в Вт</th><th>Типичное применение</th></tr></thead>\n      <tbody>\n        <tr><td>Ватт (Вт)</td><td>1 (основа)</td><td>Единица СИ, электроника, мелкая техника</td></tr>\n        <tr><td>Киловатт (кВт)</td><td>1000</td><td>Двигатели, генераторы, электротрансмиссии</td></tr>\n        <tr><td>Мегаватт (МВт)</td><td>1 000 000</td><td>Электростанции, промышленные турбины</td></tr>\n        <tr><td>Лошадиная сила (hp)</td><td>745.6998715822702</td><td>Двигатели США/Великобритании, насосы, электроинструмент</td></tr>\n        <tr><td>Метрическая лошадиная сила (PS)</td><td>735.49875</td><td>Автоспецификации ЕС/Японии/Кореи</td></tr>\n        <tr><td>BTU в час (BTU/ч)</td><td>0.29307107017222222</td><td>Кондиционеры, котлы, системы ОВиК</td></tr>\n        <tr><td>Фут-фунт в секунду (ft·lb/s)</td><td>1.3558179483314004</td><td>Задачи по физике и механике</td></tr>\n      </tbody>\n    </table>\n\n    <h3>Частые ошибки</h3>\n    <ul>\n      <li><strong>Считать hp и PS одним и тем же числом.</strong> Они близки (расхождение около 1,4 %), но двигатель «300 PS» — это не двигатель «300 hp», а скорее 296 hp.</li>\n      <li><strong>Путать мощность с крутящим моментом.</strong> В спецификациях двигателей указывают и момент (в Н·м или lb-ft) — это другая физическая величина; данный инструмент пересчитывает только единицы мощности, но не момента.</li>\n      <li><strong>Считать, что номинальные hp равны электрическим ваттам на шильдике двигателя.</strong> Значение в hp описывает механическую мощность на валу; потребляемая электрическая мощность в ваттах выше из-за потерь на КПД, поэтому не подбирайте автоматический выключатель по одному лишь пересчёту hp в ватты.</li>\n      <li><strong>Смешивать BTU (энергия) и BTU/ч (мощность).</strong> BTU/ч — это скорость, то есть мощность, тогда как просто BTU — единица энергии, точно так же как ватты и ватт-часы невзаимозаменяемы.</li>\n    </ul>\n\n    <h3>Чего этот инструмент не делает</h3>\n    <p>Это конвертер единиц, а не калькулятор КПД: он пересчитывает введённое число как есть и не учитывает эффективность двигателя, потери в трансмиссии или разницу между реальной и номинальной мощностью мотора. Для работ, связанных с электробезопасностью (подбор автоматов, проводки, нагрузки генератора), всегда используйте фактические данные с шильдика оборудования и обращайтесь к квалифицированному электрику; этот инструмент предназначен для быстрых сравнений, а не для проверки соответствия нормам.</p>",
"pt": "<style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:14px}\n      .guide-content th,.guide-content td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n    </style>\n    <h2>Por que hp, cv e kW nunca coincidem exatamente</h2>\n    <p>Os valores de potência vêm de três tradições diferentes que ainda aparecem juntas na mesma ficha técnica. Os motores de automóvel são anunciados em horsepower (hp) nos EUA e no Reino Unido, em cavalo-vapor métrico (PS ou cv) na maior parte da Europa, no Japão e na Coreia, e cada vez mais em quilowatts (kW), porque a homologação europeia e as fichas de veículos elétricos assim exigem. Eletrodomésticos e bombas costumam trazer watts ou hp na placa de identificação. Aparelhos de ar-condicionado e aquecedores são classificados em BTU/h. Nenhuma dessas unidades descreve grandezas físicas diferentes — todas são taxas de transferência de energia —, mas é ao converter de cabeça que surgem a maioria dos erros de leitura de ficha técnica, principalmente entre hp e PS, que parecem intercambiáveis e não são bem assim.</p>\n\n    <h3>Como usar</h3>\n    <ol>\n      <li>Digite o número que você tem — por exemplo o valor em hp de uma ficha de motor ou a potência em watts na etiqueta de um aparelho.</li>\n      <li>Defina <strong>De</strong> como a unidade em que o número já está e <strong>Para</strong> como a unidade desejada. O botão de troca (⇄) inverte as duas de uma vez.</li>\n      <li>Leia o resultado destacado ou role até a tabela abaixo para ver o mesmo valor expresso simultaneamente nas sete unidades.</li>\n    </ol>\n\n    <h3>A matemática: por que hp ≠ PS</h3>\n    <p>Toda conversão aqui passa pelo watt (W) como base comum, e cada fator vem de uma definição exata, e não de uma estimativa arredondada. O horsepower mecânico (hp) foi definido por James Watt a partir de cavalos girando um moinho, padronizado como exatamente <strong>550 pés-libra de trabalho por segundo</strong> — o que dá 745,6998715822702 W. O cavalo-vapor métrico (PS, do alemão <em>Pferdestärke</em>, também escrito cv ou hp(M)) é definido como <strong>75 quilogramas-força-metro por segundo</strong>, usando a gravidade padrão (9,80665 m/s²), o que resulta em exatamente 735,49875 W. Como as duas definições partem de unidades-base diferentes (pés-libra imperiais versus quilograma-força métrico), elas ficam cerca de 1,39 % distantes — próximas o bastante para confundir, distantes o bastante para importar numa ficha técnica.</p>\n\n    <h3>Exemplos resolvidos</h3>\n    <div class=\"example\"><strong>1. Comparar uma ficha europeia com uma norte-americana.</strong> Um carro anunciado como \"150 PS\" na Alemanha: 150 × 735,49875 = 110.324,8 W ≈ <strong>110,32 kW</strong> ≈ <strong>147,95 hp</strong>. Ou seja, \"150 PS\" não é bem \"150 hp\" — fica um pouco abaixo de 148 hp, diferença que vale conhecer ao comparar motores cotados em unidades distintas.</div>\n    <div class=\"example\"><strong>2. Dimensionar o circuito de um aparelho.</strong> Um aspirador de oficina ou motor de bomba de piscina de 1,5 hp: 1,5 × 745,6998715822702 ≈ <strong>1.118,5 W</strong> (cerca de 1,12 kW) de saída mecânica nominal. O consumo elétrico real é um pouco maior, porque motores não são perfeitamente eficientes — bom saber antes de ligar num circuito residencial de 15 A / 1.800 W.</div>\n    <div class=\"example\"><strong>3. Ler a classificação em BTU/h de um ar-condicionado.</strong> Um aparelho de \"1 tonelada\" é classificado em 12.000 BTU/h: 12.000 × 0,29307107017222222 ≈ 3.516,85 W ≈ <strong>3,517 kW</strong>. Esse é o valor a comparar com a potência em kW de um aparelho europeu ou com a saída de um gerador.</div>\n    <div class=\"example\"><strong>4. Dimensionar um gerador de reserva.</strong> Um gerador portátil de 5 kW, expresso em cavalos para comparar com uma ficha de motor: 5.000 ÷ 745,6998715822702 ≈ <strong>6,71 hp</strong> de saída mecânica contínua equivalente.</div>\n\n    <h3>Referência: fatores exatos de conversão para 1 W</h3>\n    <table>\n      <thead><tr><th>Unidade</th><th>1 unidade em W</th><th>Uso típico</th></tr></thead>\n      <tbody>\n        <tr><td>Watt (W)</td><td>1 (base)</td><td>Unidade SI, eletrônica, pequenos aparelhos</td></tr>\n        <tr><td>Quilowatt (kW)</td><td>1.000</td><td>Motores, geradores, sistemas de tração elétrica</td></tr>\n        <tr><td>Megawatt (MW)</td><td>1.000.000</td><td>Usinas de energia, turbinas industriais</td></tr>\n        <tr><td>Horsepower (hp)</td><td>745.6998715822702</td><td>Motores dos EUA/Reino Unido, bombas, ferramentas elétricas</td></tr>\n        <tr><td>Cavalo-vapor métrico (PS)</td><td>735.49875</td><td>Fichas de carros na UE/Japão/Coreia</td></tr>\n        <tr><td>BTU por hora (BTU/h)</td><td>0.29307107017222222</td><td>Ar-condicionado, aquecedores, HVAC</td></tr>\n        <tr><td>Pé-libra por segundo (ft·lb/s)</td><td>1.3558179483314004</td><td>Problemas de física e mecânica</td></tr>\n      </tbody>\n    </table>\n\n    <h3>Erros comuns</h3>\n    <ul>\n      <li><strong>Tratar hp e PS como o mesmo número.</strong> Eles são próximos (cerca de 1,4 % de diferença), mas um motor de \"300 PS\" não é um motor de \"300 hp\" — está mais perto de 296 hp.</li>\n      <li><strong>Confundir potência com torque.</strong> As fichas de motor também trazem o torque (em N·m ou lb-ft), uma grandeza física diferente — esta ferramenta converte apenas unidades de potência, não de torque.</li>\n      <li><strong>Supor que o hp nominal equivale aos watts elétricos na placa do motor.</strong> A potência em hp descreve a saída mecânica; a entrada elétrica em watts é maior por causa das perdas de eficiência, então não use apenas a conversão hp-watt para dimensionar um disjuntor.</li>\n      <li><strong>Misturar BTU (energia) com BTU/h (potência).</strong> BTU/h é uma taxa — potência —, enquanto o BTU simples é uma unidade de energia, do mesmo modo que watts e watt-hora não são intercambiáveis.</li>\n    </ul>\n\n    <h3>O que esta ferramenta não faz</h3>\n    <p>Este é um conversor de unidades, não uma calculadora de eficiência — ele converte o número digitado pelo valor de face e não considera a eficiência do motor, perdas na transmissão ou a diferença entre a saída real de um motor e seu valor nominal. Para trabalhos de segurança elétrica (dimensionamento de disjuntores, fiação, cargas de gerador), use sempre os valores reais da placa de identificação do equipamento e consulte um eletricista qualificado; esta ferramenta serve para comparações rápidas, não para conformidade normativa.</p>",
"de": "<style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:14px}\n      .guide-content th,.guide-content td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n    </style>\n    <h2>Warum hp, PS und kW nie ganz zusammenpassen</h2>\n    <p>Leistungsangaben stammen aus drei verschiedenen Traditionen, die alle noch auf demselben Datenblatt auftauchen. Automotoren werden in den USA und in Großbritannien in Horsepower (hp) beworben, in weiten Teilen Europas, in Japan und Korea in metrischen Pferdestärken (PS) und zunehmend in Kilowatt (kW), weil die EU-Typgenehmigung und die Datenblätter von Elektrofahrzeugen das verlangen. Haushaltsgeräte und Pumpen tragen auf dem Typenschild meist eine Angabe in Watt oder hp. Klimaanlagen und Heizkessel werden in BTU/h angegeben. Keine dieser Einheiten beschreibt eine andere physikalische Größe — es sind alles Raten der Energieübertragung —, doch beim Umrechnen aus dem Kopf entstehen die meisten Datenblattfehler, besonders zwischen hp und PS, die austauschbar aussehen und es nicht ganz sind.</p>\n\n    <h3>So verwenden Sie das Tool</h3>\n    <ol>\n      <li>Geben Sie die vorhandene Zahl ein — zum Beispiel den hp-Wert aus einem Motordatenblatt oder die Wattzahl auf einem Geräteaufkleber.</li>\n      <li>Stellen Sie <strong>Von</strong> auf die Einheit ein, in der die Zahl bereits vorliegt, und <strong>Nach</strong> auf die gewünschte Einheit. Die Tauschtaste (⇄) vertauscht beide auf einmal.</li>\n      <li>Lesen Sie das hervorgehobene Ergebnis ab oder scrollen Sie zur Tabelle darunter, um denselben Wert gleichzeitig in allen sieben Einheiten zu sehen.</li>\n    </ol>\n\n    <h3>Die Rechnung: warum hp ≠ PS</h3>\n    <p>Jede Umrechnung läuft hier über Watt (W) als gemeinsame Basis, und jeder Faktor stammt aus einer exakten Definition statt aus einer gerundeten Schätzung. Die mechanische Pferdestärke (hp) wurde von James Watt anhand von Pferden an einer Mühle definiert und auf genau <strong>550 Fuß-Pfund Arbeit pro Sekunde</strong> normiert — das ergibt 745,6998715822702 W. Die metrische Pferdestärke (PS, deutsch <em>Pferdestärke</em>, auch cv oder hp(M) geschrieben) ist dagegen als <strong>75 Kilogrammkraftmeter pro Sekunde</strong> definiert, mit der Normfallbeschleunigung (9,80665 m/s²), was genau 735,49875 W ergibt. Da beide Definitionen von unterschiedlichen Basiseinheiten ausgehen (imperiale Fuß-Pfund gegenüber metrischer Kilogrammkraft), liegen sie rund 1,39 % auseinander — nah genug zum Verwechseln, weit genug, um auf einem Datenblatt ins Gewicht zu fallen.</p>\n\n    <h3>Rechenbeispiele</h3>\n    <div class=\"example\"><strong>1. Ein europäisches Datenblatt mit einem US-Datenblatt vergleichen.</strong> Ein in Deutschland mit „150 PS“ angegebenes Auto: 150 × 735,49875 = 110.324,8 W ≈ <strong>110,32 kW</strong> ≈ <strong>147,95 hp</strong>. „150 PS“ sind also nicht ganz „150 hp“ — es sind knapp unter 148 hp, ein Unterschied, den man beim Vergleich unterschiedlich angegebener Motoren kennen sollte.</div>\n    <div class=\"example\"><strong>2. Einen Gerätestromkreis auslegen.</strong> Ein Werkstattsauger oder Poolpumpenmotor mit 1,5 hp: 1,5 × 745,6998715822702 ≈ <strong>1.118,5 W</strong> (etwa 1,12 kW) mechanische Nennleistung. Die tatsächliche elektrische Aufnahme liegt etwas höher, weil Motoren nicht perfekt effizient sind — nützlich zu wissen, bevor man an einen Haushaltsstromkreis mit 15 A / 1.800 W anschließt.</div>\n    <div class=\"example\"><strong>3. Die BTU/h-Angabe einer Klimaanlage lesen.</strong> Ein Klimagerät mit „1 Tonne“ ist mit 12.000 BTU/h angegeben: 12.000 × 0,29307107017222222 ≈ 3.516,85 W ≈ <strong>3,517 kW</strong>. Das ist der Wert, den man mit der kW-Angabe eines europäischen Geräts oder der Leistung eines Generators vergleicht.</div>\n    <div class=\"example\"><strong>4. Ein Notstromaggregat auslegen.</strong> Ein tragbarer 5-kW-Generator, in Pferdestärken für den Vergleich mit einem Motordatenblatt ausgedrückt: 5.000 ÷ 745,6998715822702 ≈ <strong>6,71 hp</strong> äquivalente mechanische Dauerleistung.</div>\n\n    <h3>Referenz: exakte Umrechnungsfaktoren auf 1 W</h3>\n    <table>\n      <thead><tr><th>Einheit</th><th>1 Einheit in W</th><th>Typische Verwendung</th></tr></thead>\n      <tbody>\n        <tr><td>Watt (W)</td><td>1 (Basis)</td><td>SI-Einheit, Elektronik, Kleingeräte</td></tr>\n        <tr><td>Kilowatt (kW)</td><td>1.000</td><td>Motoren, Generatoren, E-Antriebe</td></tr>\n        <tr><td>Megawatt (MW)</td><td>1.000.000</td><td>Kraftwerke, Industrieturbinen</td></tr>\n        <tr><td>Horsepower (hp)</td><td>745.6998715822702</td><td>US-/UK-Motoren, Pumpen, Elektrowerkzeuge</td></tr>\n        <tr><td>Metrische Pferdestärke (PS)</td><td>735.49875</td><td>Fahrzeugdaten in EU/Japan/Korea</td></tr>\n        <tr><td>BTU pro Stunde (BTU/h)</td><td>0.29307107017222222</td><td>Klimaanlagen, Heizkessel, HLK</td></tr>\n        <tr><td>Fuß-Pfund pro Sekunde (ft·lb/s)</td><td>1.3558179483314004</td><td>Aufgaben aus Physik und Mechanik</td></tr>\n      </tbody>\n    </table>\n\n    <h3>Häufige Fehler</h3>\n    <ul>\n      <li><strong>hp und PS als dieselbe Zahl behandeln.</strong> Sie liegen nah beieinander (rund 1,4 % Unterschied), aber ein „300 PS“-Motor ist kein „300 hp“-Motor — er liegt eher bei 296 hp.</li>\n      <li><strong>Leistung mit Drehmoment verwechseln.</strong> Motordatenblätter nennen auch das Drehmoment (in N·m oder lb-ft), eine andere physikalische Größe — dieses Tool rechnet nur Leistungseinheiten um, kein Drehmoment.</li>\n      <li><strong>Annehmen, die Nenn-hp entsprächen den elektrischen Watt auf dem Motortypenschild.</strong> Die hp-Angabe eines Motors beschreibt die mechanische Abgabeleistung; die elektrische Aufnahme in Watt ist wegen der Wirkungsgradverluste höher — verwenden Sie die hp-Watt-Umrechnung daher nicht allein zur Auslegung eines Leitungsschutzschalters.</li>\n      <li><strong>BTU (Energie) mit BTU/h (Leistung) verwechseln.</strong> BTU/h ist eine Rate — Leistung —, während ein reines BTU eine Energieeinheit ist, genauso wie Watt und Wattstunden nicht austauschbar sind.</li>\n    </ul>\n\n    <h3>Was dieses Tool nicht leistet</h3>\n    <p>Dies ist ein Einheitenumrechner, kein Wirkungsgradrechner — er rechnet die eingegebene Zahl unverändert um und kann weder Motorwirkungsgrad noch Antriebsstrangverluste noch die Abweichung zwischen realer und angegebener Motorleistung berücksichtigen. Für Arbeiten an der elektrischen Sicherheit (Auslegung von Schutzschaltern, Verkabelung, Generatorlasten) verwenden Sie stets die tatsächlichen Typenschildangaben und ziehen Sie eine Elektrofachkraft hinzu; dieses Tool dient dem schnellen Vergleich, nicht der Normkonformität.</p>",
"fr": "<style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:14px}\n      .guide-content th,.guide-content td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n    </style>\n    <h2>Pourquoi hp, ch et kW ne coïncident jamais tout à fait</h2>\n    <p>Les valeurs de puissance proviennent de trois traditions différentes qui figurent toutes sur la même fiche technique. Les moteurs automobiles sont commercialisés en chevaux-vapeur (hp) aux États-Unis et au Royaume-Uni, en chevaux métriques (PS, ch) dans la plupart des pays d'Europe, au Japon et en Corée, et de plus en plus en kilowatts (kW), car l'homologation européenne et les fiches des véhicules électriques l'exigent. Les appareils domestiques et les pompes sont généralement notés en watts ou en hp sur la plaque signalétique. Les climatiseurs et les chaudières sont notés en BTU/h. Aucune de ces unités ne décrit une grandeur physique différente — ce sont toutes des taux de transfert d'énergie — mais c'est en convertissant de mémoire que surviennent la plupart des erreurs de lecture, en particulier entre hp et PS, qui semblent interchangeables et ne le sont pas tout à fait.</p>\n\n    <h3>Comment l'utiliser</h3>\n    <ol>\n      <li>Saisissez le nombre dont vous disposez — par exemple la valeur en hp d'une fiche moteur ou la puissance en watts d'une étiquette d'appareil.</li>\n      <li>Réglez <strong>De</strong> sur l'unité dans laquelle ce nombre est déjà exprimé, et <strong>Vers</strong> sur l'unité souhaitée. Le bouton d'inversion (⇄) permute les deux d'un seul coup.</li>\n      <li>Lisez le résultat mis en évidence, ou faites défiler le tableau ci-dessous pour voir la même valeur exprimée simultanément dans les sept unités.</li>\n    </ol>\n\n    <h3>Le calcul : pourquoi hp ≠ PS</h3>\n    <p>Chaque conversion passe ici par le watt (W) comme base commune, et chaque facteur découle d'une définition exacte plutôt que d'une estimation arrondie. Le cheval-vapeur mécanique (hp) a été défini par James Watt à partir de chevaux actionnant un moulin, normalisé à exactement <strong>550 pieds-livres de travail par seconde</strong> — ce qui donne 745,6998715822702 W. Le cheval-vapeur métrique (PS, de l'allemand <em>Pferdestärke</em>, aussi écrit cv ou hp(M)) est défini quant à lui comme <strong>75 kilogrammes-force-mètres par seconde</strong>, avec la gravité normale (9,80665 m/s²), soit exactement 735,49875 W. Comme les deux définitions partent d'unités de base différentes (pieds-livres impériaux contre kilogrammes-force métriques), elles diffèrent d'environ 1,39 % — assez proches pour prêter à confusion, assez éloignées pour compter sur une fiche technique.</p>\n\n    <h3>Exemples concrets</h3>\n    <div class=\"example\"><strong>1. Comparer une fiche européenne à une fiche américaine.</strong> Une voiture annoncée à « 150 PS » en Allemagne : 150 × 735,49875 = 110 324,8 W ≈ <strong>110,32 kW</strong> ≈ <strong>147,95 hp</strong>. Ainsi, « 150 PS » n'est pas tout à fait « 150 hp » — c'est un peu moins de 148 hp, un écart utile à connaître lorsqu'on compare des moteurs annoncés dans des unités différentes.</div>\n    <div class=\"example\"><strong>2. Dimensionner un circuit d'appareil.</strong> Un aspirateur d'atelier ou un moteur de pompe de piscine de 1,5 hp : 1,5 × 745,6998715822702 ≈ <strong>1 118,5 W</strong> (environ 1,12 kW) de puissance mécanique nominale. La consommation électrique réelle est un peu plus élevée, car les moteurs ne sont pas parfaitement efficaces — bon à savoir avant de brancher sur un circuit domestique de 15 A / 1 800 W.</div>\n    <div class=\"example\"><strong>3. Lire la puissance en BTU/h d'un climatiseur.</strong> Un climatiseur « 1 tonne » est noté 12 000 BTU/h : 12 000 × 0,29307107017222222 ≈ 3 516,85 W ≈ <strong>3,517 kW</strong>. C'est la valeur à comparer à la puissance en kW d'un appareil européen ou au rendement d'un groupe électrogène.</div>\n    <div class=\"example\"><strong>4. Dimensionner un groupe électrogène de secours.</strong> Un groupe portable de 5 kW, exprimé en chevaux pour comparer avec une fiche moteur : 5 000 ÷ 745,6998715822702 ≈ <strong>6,71 hp</strong> de puissance mécanique continue équivalente.</div>\n\n    <h3>Référence : facteurs de conversion exacts vers 1 W</h3>\n    <table>\n      <thead><tr><th>Unité</th><th>1 unité en W</th><th>Usage courant</th></tr></thead>\n      <tbody>\n        <tr><td>Watt (W)</td><td>1 (base)</td><td>Unité SI, électronique, petits appareils</td></tr>\n        <tr><td>Kilowatt (kW)</td><td>1 000</td><td>Moteurs, générateurs, chaînes de traction électriques</td></tr>\n        <tr><td>Mégawatt (MW)</td><td>1 000 000</td><td>Centrales électriques, turbines industrielles</td></tr>\n        <tr><td>Cheval-vapeur (hp)</td><td>745.6998715822702</td><td>Moteurs US/UK, pompes, outils électriques</td></tr>\n        <tr><td>Cheval métrique (PS)</td><td>735.49875</td><td>Fiches auto UE/Japon/Corée</td></tr>\n        <tr><td>BTU par heure (BTU/h)</td><td>0.29307107017222222</td><td>Climatiseurs, chaudières, CVC</td></tr>\n        <tr><td>Pied-livre par seconde (ft·lb/s)</td><td>1.3558179483314004</td><td>Problèmes de physique et de mécanique</td></tr>\n      </tbody>\n    </table>\n\n    <h3>Erreurs fréquentes</h3>\n    <ul>\n      <li><strong>Considérer hp et PS comme le même nombre.</strong> Ils sont proches (environ 1,4 % d'écart) mais un moteur de « 300 PS » n'est pas un moteur de « 300 hp » — il est plus proche de 296 hp.</li>\n      <li><strong>Confondre puissance et couple.</strong> Les fiches moteur indiquent aussi le couple (en N·m ou lb-ft), une grandeur physique différente — cet outil convertit uniquement des unités de puissance, pas de couple.</li>\n      <li><strong>Supposer que les hp nominaux équivalent aux watts électriques sur une plaque moteur.</strong> La puissance en hp d'un moteur décrit sa sortie mécanique ; l'entrée électrique en watts est plus élevée à cause des pertes de rendement, n'utilisez donc pas la seule conversion hp-watt pour dimensionner un disjoncteur.</li>\n      <li><strong>Confondre BTU (énergie) et BTU/h (puissance).</strong> Le BTU/h est un débit — une puissance — alors qu'un BTU seul est une unité d'énergie, de la même façon que watts et wattheures ne sont pas interchangeables.</li>\n    </ul>\n\n    <h3>Ce que cet outil ne fait pas</h3>\n    <p>Il s'agit d'un convertisseur d'unités, pas d'un calculateur de rendement — il convertit le nombre saisi tel quel et ne peut pas tenir compte du rendement du moteur, des pertes de transmission ou de l'écart entre la puissance réelle d'un moteur et sa valeur nominale. Pour tout travail de sécurité électrique (calibrage de disjoncteur, câblage, charges de groupe électrogène), utilisez toujours les valeurs réelles de la plaque signalétique et consultez un électricien qualifié ; cet outil sert aux comparaisons rapides, pas à la conformité aux normes.</p>",
"es": "<style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:14px}\n      .guide-content th,.guide-content td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n    </style>\n<h2>Por qu\u00e9 hp, PS y kW nunca terminan de coincidir</h2>\n    <p>Las cifras de potencia proceden de tres tradiciones distintas que a\u00fan hoy aparecen juntas en la misma ficha t\u00e9cnica. Los motores de coche se anuncian en caballos de fuerza (hp) en Estados Unidos y el Reino Unido, en caballos de vapor m\u00e9tricos (PS o CV) en casi toda Europa, Jap\u00f3n y Corea, y cada vez m\u00e1s en kilovatios (kW), porque as\u00ed lo exigen la homologaci\u00f3n europea y las especificaciones de los veh\u00edculos el\u00e9ctricos. Los electrodom\u00e9sticos y las bombas suelen indicar vatios o hp en la placa de caracter\u00edsticas. Los aires acondicionados y las calderas se especifican en BTU/h. Ninguna de estas unidades describe magnitudes f\u00edsicas distintas \u2014todas son tasas de transferencia de energ\u00eda\u2014, pero convertirlas de memoria es donde se cometen la mayor\u00eda de los errores con las fichas t\u00e9cnicas, sobre todo entre hp y PS, que parecen intercambiables y no lo son del todo.</p>\n\n    <h3>C\u00f3mo usarlo</h3>\n    <ol>\n      <li>Introduce el n\u00famero que tengas: por ejemplo, la cifra en hp de un motor o el vataje de la etiqueta de un electrodom\u00e9stico.</li>\n      <li>Pon <strong>De</strong> en la unidad en la que ya est\u00e1 ese n\u00famero y <strong>A</strong> en la unidad que quieres obtener. El bot\u00f3n de intercambio (\u21c4) invierte ambas a la vez.</li>\n      <li>Lee el resultado destacado o consulta la tabla inferior para ver el mismo valor expresado en las siete unidades a la vez.</li>\n    </ol>\n\n    <h3>Las matem\u00e1ticas: por qu\u00e9 hp \u2260 PS</h3>\n    <p>Todas las conversiones pasan por el vatio (W) como base com\u00fan, y cada factor procede de una definici\u00f3n exacta y no de una estimaci\u00f3n redondeada. El caballo de fuerza mec\u00e1nico (hp) lo defini\u00f3 James Watt a partir de caballos moviendo un molino y se normaliz\u00f3 como exactamente <strong>550 libras-pie de trabajo por segundo</strong>, lo que equivale a 745,6998715822702 W. El caballo de vapor m\u00e9trico (PS, del alem\u00e1n <em>Pferdest\u00e4rke</em>, tambi\u00e9n escrito cv o hp(M)) se define en cambio como <strong>75 kilogramos-fuerza-metro por segundo</strong>, con la gravedad est\u00e1ndar (9,80665 m/s\u00b2), lo que da exactamente 735,49875 W. Como ambas definiciones parten de unidades base distintas (libras-pie imperiales frente a kilogramos-fuerza m\u00e9tricos), quedan separadas alrededor de un 1,39%: lo bastante cerca para confundir y lo bastante lejos para importar en una ficha t\u00e9cnica.</p>\n\n    <h3>Ejemplos resueltos</h3>\n    <div class=\"example\"><strong>1. Comparar una ficha europea con una estadounidense.</strong> Un coche anunciado como \u00ab150 PS\u00bb en Alemania: 150 \u00d7 735,49875 = 110.324,8 W \u2248 <strong>110,32 kW</strong> \u2248 <strong>147,95 hp</strong>. As\u00ed que \u00ab150 PS\u00bb no es exactamente \u00ab150 hp\u00bb: se queda algo por debajo de 148 hp, una diferencia que conviene conocer al comparar motores expresados en unidades distintas.</div>\n    <div class=\"example\"><strong>2. Dimensionar el circuito de un aparato.</strong> Un aspirador de taller o una bomba de piscina de 1,5 hp: 1,5 \u00d7 745,6998715822702 \u2248 <strong>1.118,5 W</strong> (unos 1,12 kW) de potencia mec\u00e1nica nominal. El consumo el\u00e9ctrico real es algo mayor, porque los motores no son perfectamente eficientes: \u00fatil saberlo antes de enchufarlo a un circuito dom\u00e9stico de 15 A / 1.800 W.</div>\n    <div class=\"example\"><strong>3. Interpretar los BTU/h de un aire acondicionado.</strong> Un equipo \u00abde 1 tonelada\u00bb tiene 12.000 BTU/h: 12.000 \u00d7 0,29307107017222222 \u2248 3.516,85 W \u2248 <strong>3,517 kW</strong>. Esa es la cifra que hay que comparar con los kW de un equipo europeo o con la salida de un generador.</div>\n    <div class=\"example\"><strong>4. Dimensionar un generador de respaldo.</strong> Un generador port\u00e1til de 5 kW, expresado en caballos para compararlo con la ficha de un motor: 5.000 \u00f7 745,6998715822702 \u2248 <strong>6,71 hp</strong> de potencia mec\u00e1nica continua equivalente.</div>\n\n    <h3>Referencia: factores de conversi\u00f3n exactos a 1 W</h3>\n    <table>\n      <thead><tr><th>Unidad</th><th>1 unidad en W</th><th>Uso habitual</th></tr></thead>\n      <tbody>\n        <tr><td>Vatio (W)</td><td>1 (base)</td><td>Unidad del SI, electr\u00f3nica, peque\u00f1os electrodom\u00e9sticos</td></tr>\n        <tr><td>Kilovatio (kW)</td><td>1.000</td><td>Motores, generadores, propulsi\u00f3n el\u00e9ctrica</td></tr>\n        <tr><td>Megavatio (MW)</td><td>1.000.000</td><td>Centrales el\u00e9ctricas, turbinas industriales</td></tr>\n        <tr><td>Caballo de fuerza (hp)</td><td>745.6998715822702</td><td>Motores de EE. UU./Reino Unido, bombas, herramientas</td></tr>\n        <tr><td>Caballo de vapor m\u00e9trico (PS)</td><td>735.49875</td><td>Fichas de coches de UE/Jap\u00f3n/Corea</td></tr>\n        <tr><td>BTU por hora (BTU/h)</td><td>0.29307107017222222</td><td>Aire acondicionado, calderas, climatizaci\u00f3n</td></tr>\n        <tr><td>Libra-pie por segundo (ft\u00b7lb/s)</td><td>1.3558179483314004</td><td>Problemas de f\u00edsica y mec\u00e1nica</td></tr>\n      </tbody>\n    </table>\n\n    <h3>Errores frecuentes</h3>\n    <ul>\n      <li><strong>Tratar hp y PS como el mismo n\u00famero.</strong> Est\u00e1n cerca (un 1,4% de diferencia), pero un motor de \u00ab300 PS\u00bb no es un motor de \u00ab300 hp\u00bb: se acerca m\u00e1s a 296 hp.</li>\n      <li><strong>Confundir potencia con par motor.</strong> Las fichas tambi\u00e9n indican el par (en N\u00b7m o lb-ft), que es otra magnitud f\u00edsica: esta herramienta convierte solo unidades de potencia, no de par.</li>\n      <li><strong>Suponer que los hp nominales equivalen a los vatios el\u00e9ctricos de la placa de un motor.</strong> Los hp de un motor describen la salida mec\u00e1nica; la entrada el\u00e9ctrica en vatios es mayor por las p\u00e9rdidas de eficiencia, as\u00ed que no uses solo la conversi\u00f3n hp-vatios para dimensionar un magnetot\u00e9rmico.</li>\n      <li><strong>Mezclar BTU (energ\u00eda) con BTU/h (potencia).</strong> BTU/h es una tasa \u2014potencia\u2014, mientras que un BTU a secas es una unidad de energ\u00eda, igual que los vatios y los vatios-hora no son intercambiables.</li>\n    </ul>\n\n    <h3>Lo que esta herramienta no hace</h3>\n    <p>Es un conversor de unidades, no una calculadora de eficiencia: convierte el n\u00famero que escribes tal cual y no puede tener en cuenta el rendimiento del motor, las p\u00e9rdidas de transmisi\u00f3n ni la diferencia entre la potencia real y la nominal de un motor. Para trabajos de seguridad el\u00e9ctrica (dimensionado de protecciones, cableado, cargas de generadores), usa siempre los valores reales de la placa de caracter\u00edsticas del equipo y consulta a un electricista cualificado; esta herramienta sirve para comparaciones r\u00e1pidas, no para verificar el cumplimiento normativo.</p>",
"zh": "<style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:14px}\n      .guide-content th,.guide-content td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n    </style>\n<h2>\u4e3a\u4ec0\u4e48 hp\u3001PS \u548c kW \u4ece\u6765\u5bf9\u4e0d\u4e0a</h2>\n    <p>\u529f\u7387\u6807\u79f0\u6765\u81ea\u4e09\u5957\u4e0d\u540c\u7684\u4f20\u7edf\uff0c\u800c\u5b83\u4eec\u81f3\u4eca\u4ecd\u4f1a\u51fa\u73b0\u5728\u540c\u4e00\u5f20\u53c2\u6570\u8868\u4e0a\u3002\u6c7d\u8f66\u53d1\u52a8\u673a\u5728\u7f8e\u56fd\u548c\u82f1\u56fd\u7528\u9a6c\u529b\uff08hp\uff09\u6807\u793a\uff0c\u5728\u6b27\u6d32\u5927\u90e8\u5206\u5730\u533a\u4ee5\u53ca\u65e5\u672c\u3001\u97e9\u56fd\u7528\u516c\u5236\u9a6c\u529b\uff08PS\uff09\u6807\u793a\uff0c\u800c\u7531\u4e8e\u6b27\u76df\u578b\u5f0f\u8ba4\u8bc1\u548c\u7535\u52a8\u8f66\u89c4\u683c\u7684\u8981\u6c42\uff0c\u7528\u5343\u74e6\uff08kW\uff09\u6807\u793a\u7684\u60c5\u51b5\u4e5f\u8d8a\u6765\u8d8a\u591a\u3002\u5bb6\u7528\u7535\u5668\u548c\u6c34\u6cf5\u901a\u5e38\u5728\u94ed\u724c\u4e0a\u6807\u6ce8\u74e6\u7279\u6216 hp\uff0c\u7a7a\u8c03\u548c\u6696\u7089\u5219\u4ee5 BTU/h \u6807\u6ce8\u3002\u8fd9\u4e9b\u5e76\u4e0d\u662f\u4e0d\u540c\u7684\u7269\u7406\u91cf\u2014\u2014\u5b83\u4eec\u90fd\u662f\u80fd\u91cf\u4f20\u9012\u7684\u901f\u7387\uff0c\u4e5f\u5c31\u662f\u529f\u7387\u2014\u2014\u4f46\u51ed\u8bb0\u5fc6\u6362\u7b97\u6b63\u662f\u53c2\u6570\u8868\u51fa\u9519\u6700\u591a\u7684\u5730\u65b9\uff0c\u5c24\u5176\u662f\u5728\u770b\u8d77\u6765\u53ef\u4ee5\u4e92\u6362\u3001\u5b9e\u9645\u4e0a\u5e76\u4e0d\u76f8\u7b49\u7684 hp \u4e0e PS \u4e4b\u95f4\u3002</p>\n\n    <h3>\u4f7f\u7528\u65b9\u6cd5</h3>\n    <ol>\n      <li>\u8f93\u5165\u4f60\u624b\u4e0a\u7684\u6570\u503c\u2014\u2014\u4f8b\u5982\u53d1\u52a8\u673a\u53c2\u6570\u4e2d\u7684 hp \u6570\u5b57\uff0c\u6216\u7535\u5668\u6807\u7b7e\u4e0a\u7684\u74e6\u6570\u3002</li>\n      <li>\u628a<strong>\u6e90\u5355\u4f4d</strong>\u8bbe\u4e3a\u8be5\u6570\u503c\u5f53\u524d\u6240\u7528\u7684\u5355\u4f4d\uff0c\u628a<strong>\u76ee\u6807\u5355\u4f4d</strong>\u8bbe\u4e3a\u4f60\u60f3\u8981\u7684\u5355\u4f4d\u3002\u4e92\u6362\u6309\u94ae\uff08\u21c4\uff09\u53ef\u4e00\u6b21\u8c03\u6362\u4e24\u8005\u3002</li>\n      <li>\u8bfb\u53d6\u9ad8\u4eae\u663e\u793a\u7684\u7ed3\u679c\uff0c\u6216\u8005\u6d4f\u89c8\u4e0b\u65b9\u8868\u683c\uff0c\u540c\u65f6\u67e5\u770b\u540c\u4e00\u6570\u503c\u5728\u5168\u90e8\u4e03\u79cd\u5355\u4f4d\u4e0b\u7684\u8868\u793a\u3002</li>\n    </ol>\n\n    <h3>\u7b97\u6cd5\u539f\u7406\uff1a\u4e3a\u4ec0\u4e48 hp \u2260 PS</h3>\n    <p>\u8fd9\u91cc\u6240\u6709\u6362\u7b97\u90fd\u4ee5\u74e6\u7279\uff08W\uff09\u4f5c\u4e3a\u5171\u540c\u57fa\u51c6\uff0c\u6bcf\u4e2a\u7cfb\u6570\u90fd\u6765\u81ea\u7cbe\u786e\u5b9a\u4e49\u800c\u975e\u56db\u820d\u4e94\u5165\u7684\u4f30\u8ba1\u503c\u3002\u673a\u68b0\u9a6c\u529b\uff08hp\uff09\u7531\u8a79\u59c6\u65af\u00b7\u74e6\u7279\u6839\u636e\u63a8\u78e8\u7684\u9a6c\u5b9a\u4e49\uff0c\u6807\u51c6\u5316\u4e3a\u6070\u597d<strong>\u6bcf\u79d2 550 \u82f1\u5c3a\u78c5\u7684\u529f</strong>\uff0c\u6362\u7b97\u540e\u4e3a 745.6998715822702 W\u3002\u516c\u5236\u9a6c\u529b\uff08PS\uff0c\u5fb7\u8bed <em>Pferdest\u00e4rke</em>\uff0c\u4e5f\u5199\u4f5c cv \u6216 hp(M)\uff09\u5219\u4ee5\u6807\u51c6\u91cd\u529b\uff089.80665 m/s\u00b2\uff09\u5b9a\u4e49\u4e3a<strong>\u6bcf\u79d2 75 \u5343\u514b\u529b\u7c73</strong>\uff0c\u6070\u597d\u7b49\u4e8e 735.49875 W\u3002\u7531\u4e8e\u4e24\u79cd\u5b9a\u4e49\u51fa\u53d1\u7684\u57fa\u672c\u5355\u4f4d\u4e0d\u540c\uff08\u82f1\u5236\u7684\u82f1\u5c3a\u78c5\u5bf9\u516c\u5236\u7684\u5343\u514b\u529b\uff09\uff0c\u4e24\u8005\u76f8\u5dee\u7ea6 1.39%\u2014\u2014\u8fd1\u5230\u8db3\u4ee5\u8ba9\u4eba\u6df7\u6dc6\uff0c\u53c8\u8fdc\u5230\u5728\u53c2\u6570\u8868\u4e0a\u4e0d\u53ef\u5ffd\u89c6\u3002</p>\n\n    <h3>\u5b9e\u4f8b\u8ba1\u7b97</h3>\n    <div class=\"example\"><strong>1. \u5bf9\u6bd4\u6b27\u6d32\u53c2\u6570\u8868\u4e0e\u7f8e\u56fd\u53c2\u6570\u8868\u3002</strong> \u5728\u5fb7\u56fd\u6807\u4e3a\u201c150 PS\u201d\u7684\u8f66\uff1a150 \u00d7 735.49875 = 110,324.8 W \u2248 <strong>110.32 kW</strong> \u2248 <strong>147.95 hp</strong>\u3002\u6240\u4ee5\u201c150 PS\u201d\u5e76\u4e0d\u7b49\u4e8e\u201c150 hp\u201d\uff0c\u800c\u662f\u7565\u4f4e\u4e8e 148 hp\u3002\u5728\u6bd4\u8f83\u4ee5\u4e0d\u540c\u5355\u4f4d\u6807\u79f0\u7684\u53d1\u52a8\u673a\u65f6\uff0c\u8fd9\u4e2a\u5dee\u8ddd\u503c\u5f97\u7559\u610f\u3002</div>\n    <div class=\"example\"><strong>2. \u4f30\u7b97\u7535\u5668\u56de\u8def\u5bb9\u91cf\u3002</strong> \u4e00\u53f0 1.5 hp \u7684\u8f66\u95f4\u5438\u5c18\u5668\u6216\u6cf3\u6c60\u6c34\u6cf5\u7535\u673a\uff1a1.5 \u00d7 745.6998715822702 \u2248 <strong>1,118.5 W</strong>\uff08\u7ea6 1.12 kW\uff09\u7684\u989d\u5b9a\u673a\u68b0\u8f93\u51fa\u3002\u7531\u4e8e\u7535\u673a\u5e76\u975e\u767e\u5206\u4e4b\u767e\u9ad8\u6548\uff0c\u5b9e\u9645\u7528\u7535\u7565\u9ad8\u4e8e\u6b64\u503c\u2014\u2014\u5728\u63a5\u5165 15 A / 1,800 W \u5bb6\u7528\u56de\u8def\u524d\u503c\u5f97\u5148\u4e86\u89e3\u3002</div>\n    <div class=\"example\"><strong>3. \u8bfb\u61c2\u7a7a\u8c03\u7684 BTU/h \u6807\u79f0\u3002</strong> \u4e00\u53f0\u201c1 \u5339\uff081 \u5428\uff09\u201d\u7a7a\u8c03\u7684\u989d\u5b9a\u503c\u4e3a 12,000 BTU/h\uff1a12,000 \u00d7 0.29307107017222222 \u2248 3,516.85 W \u2248 <strong>3.517 kW</strong>\u3002\u8fd9\u6b63\u662f\u62ff\u6765\u4e0e\u6b27\u6d32\u4ea7\u54c1\u7684 kW \u6807\u79f0\u6216\u53d1\u7535\u673a\u8f93\u51fa\u4f5c\u6bd4\u8f83\u7684\u6570\u5b57\u3002</div>\n    <div class=\"example\"><strong>4. \u4f30\u7b97\u5907\u7528\u53d1\u7535\u673a\u5bb9\u91cf\u3002</strong> \u4e00\u53f0 5 kW \u4fbf\u643a\u5f0f\u53d1\u7535\u673a\uff0c\u4e3a\u4e0e\u53d1\u52a8\u673a\u53c2\u6570\u6bd4\u8f83\u800c\u6362\u7b97\u6210\u9a6c\u529b\uff1a5,000 \u00f7 745.6998715822702 \u2248 <strong>6.71 hp</strong> \u7684\u8fde\u7eed\u673a\u68b0\u8f93\u51fa\u5f53\u91cf\u3002</div>\n\n    <h3>\u53c2\u8003\uff1a\u4ee5 1 W \u4e3a\u57fa\u51c6\u7684\u7cbe\u786e\u6362\u7b97\u7cfb\u6570</h3>\n    <table>\n      <thead><tr><th>\u5355\u4f4d</th><th>1 \u5355\u4f4d\u7b49\u4e8e\u591a\u5c11 W</th><th>\u5178\u578b\u7528\u9014</th></tr></thead>\n      <tbody>\n        <tr><td>\u74e6\u7279 (W)</td><td>1\uff08\u57fa\u51c6\uff09</td><td>\u56fd\u9645\u5355\u4f4d\u5236\u5355\u4f4d\u3001\u7535\u5b50\u8bbe\u5907\u3001\u5c0f\u5bb6\u7535</td></tr>\n        <tr><td>\u5343\u74e6 (kW)</td><td>1,000</td><td>\u7535\u673a\u3001\u53d1\u7535\u673a\u3001\u7535\u52a8\u8f66\u52a8\u529b\u7cfb\u7edf</td></tr>\n        <tr><td>\u5146\u74e6 (MW)</td><td>1,000,000</td><td>\u53d1\u7535\u5382\u3001\u5de5\u4e1a\u6da1\u8f6e\u673a</td></tr>\n        <tr><td>\u9a6c\u529b (hp)</td><td>745.6998715822702</td><td>\u7f8e\u82f1\u53d1\u52a8\u673a\u3001\u6c34\u6cf5\u3001\u7535\u52a8\u5de5\u5177</td></tr>\n        <tr><td>\u516c\u5236\u9a6c\u529b (PS)</td><td>735.49875</td><td>\u6b27\u6d32\uff0f\u65e5\u672c\uff0f\u97e9\u56fd\u6c7d\u8f66\u53c2\u6570</td></tr>\n        <tr><td>\u82f1\u70ed\u5355\u4f4d\u6bcf\u5c0f\u65f6 (BTU/h)</td><td>0.29307107017222222</td><td>\u7a7a\u8c03\u3001\u6696\u7089\u3001\u6696\u901a\u7a7a\u8c03</td></tr>\n        <tr><td>\u82f1\u5c3a\u78c5\u6bcf\u79d2 (ft\u00b7lb/s)</td><td>1.3558179483314004</td><td>\u7269\u7406\u4e0e\u529b\u5b66\u9898\u76ee</td></tr>\n      </tbody>\n    </table>\n\n    <h3>\u5e38\u89c1\u9519\u8bef</h3>\n    <ul>\n      <li><strong>\u628a hp \u548c PS \u5f53\u6210\u540c\u4e00\u4e2a\u6570\u3002</strong> \u4e24\u8005\u76f8\u5dee\u7ea6 1.4%\uff0c\u5f88\u63a5\u8fd1\uff0c\u4f46\u201c300 PS\u201d\u7684\u53d1\u52a8\u673a\u5e76\u4e0d\u662f\u201c300 hp\u201d\u7684\u53d1\u52a8\u673a\uff0c\u800c\u662f\u63a5\u8fd1 296 hp\u3002</li>\n      <li><strong>\u6df7\u6dc6\u529f\u7387\u4e0e\u626d\u77e9\u3002</strong> \u53d1\u52a8\u673a\u53c2\u6570\u8fd8\u4f1a\u5217\u51fa\u626d\u77e9\uff08\u5355\u4f4d N\u00b7m \u6216 lb-ft\uff09\uff0c\u90a3\u662f\u53e6\u4e00\u79cd\u7269\u7406\u91cf\u2014\u2014\u672c\u5de5\u5177\u53ea\u6362\u7b97\u529f\u7387\u5355\u4f4d\uff0c\u4e0d\u5904\u7406\u626d\u77e9\u3002</li>\n      <li><strong>\u4ee5\u4e3a\u7535\u673a\u94ed\u724c\u7684\u989d\u5b9a hp \u5c31\u7b49\u4e8e\u7535\u529f\u7387\u74e6\u6570\u3002</strong> \u7535\u673a\u7684 hp \u989d\u5b9a\u503c\u63cf\u8ff0\u7684\u662f\u673a\u68b0\u8f93\u51fa\uff0c\u800c\u4ee5\u74e6\u7279\u8ba1\u7684\u7535\u8f93\u5165\u56e0\u6548\u7387\u635f\u5931\u800c\u66f4\u9ad8\uff0c\u56e0\u6b64\u4e0d\u8981\u53ea\u51ed hp \u8f6c\u74e6\u7279\u7684\u6362\u7b97\u6765\u9009\u65ad\u8def\u5668\u3002</li>\n      <li><strong>\u628a BTU\uff08\u80fd\u91cf\uff09\u4e0e BTU/h\uff08\u529f\u7387\uff09\u641e\u6df7\u3002</strong> BTU/h \u662f\u901f\u7387\uff0c\u5373\u529f\u7387\uff1b\u800c\u5355\u7eaf\u7684 BTU \u662f\u80fd\u91cf\u5355\u4f4d\uff0c\u6b63\u5982\u74e6\u7279\u4e0e\u74e6\u65f6\u4e0d\u80fd\u4e92\u6362\u4e00\u6837\u3002</li>\n    </ul>\n\n    <h3>\u672c\u5de5\u5177\u4e0d\u505a\u4ec0\u4e48</h3>\n    <p>\u8fd9\u662f\u4e00\u4e2a\u5355\u4f4d\u6362\u7b97\u5668\uff0c\u800c\u4e0d\u662f\u6548\u7387\u8ba1\u7b97\u5668\u2014\u2014\u5b83\u6309\u5b57\u9762\u6362\u7b97\u4f60\u8f93\u5165\u7684\u6570\u503c\uff0c\u65e0\u6cd5\u8003\u8651\u7535\u673a\u6548\u7387\u3001\u4f20\u52a8\u635f\u5931\uff0c\u6216\u53d1\u52a8\u673a\u5b9e\u9645\u8f93\u51fa\u4e0e\u989d\u5b9a\u503c\u4e4b\u95f4\u7684\u5dee\u5f02\u3002\u6d89\u53ca\u7535\u6c14\u5b89\u5168\u7684\u5de5\u4f5c\uff08\u65ad\u8def\u5668\u9009\u578b\u3001\u5e03\u7ebf\u3001\u53d1\u7535\u673a\u8d1f\u8f7d\uff09\u8bf7\u59cb\u7ec8\u4ee5\u8bbe\u5907\u5b9e\u9645\u94ed\u724c\u53c2\u6570\u4e3a\u51c6\uff0c\u5e76\u54a8\u8be2\u6709\u8d44\u8d28\u7684\u7535\u5de5\uff1b\u672c\u5de5\u5177\u7528\u4e8e\u5feb\u901f\u6bd4\u8f83\uff0c\u4e0d\u7528\u4e8e\u5408\u89c4\u5224\u5b9a\u3002</p>",
"ja": "<style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:14px}\n      .guide-content th,.guide-content td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n    </style>\n<h2>hp\u30fbPS\u30fbkW \u304c\u3074\u3063\u305f\u308a\u4e00\u81f4\u3057\u306a\u3044\u7406\u7531</h2>\n    <p>\u51fa\u529b\u306e\u8868\u8a18\u306f\u4e09\u3064\u306e\u7570\u306a\u308b\u4f1d\u7d71\u304b\u3089\u751f\u307e\u308c\u3001\u4eca\u3067\u3082\u540c\u3058\u30b9\u30da\u30c3\u30af\u8868\u306b\u6df7\u5728\u3057\u3066\u3044\u307e\u3059\u3002\u81ea\u52d5\u8eca\u306e\u30a8\u30f3\u30b8\u30f3\u306f\u3001\u7c73\u56fd\u30fb\u82f1\u56fd\u3067\u306f\u99ac\u529b\uff08hp\uff09\u3001\u30e8\u30fc\u30ed\u30c3\u30d1\u306e\u5927\u534a\u3068\u65e5\u672c\u30fb\u97d3\u56fd\u3067\u306f\u30e1\u30fc\u30c8\u30eb\u99ac\u529b\uff08PS\uff09\u3067\u8868\u8a18\u3055\u308c\u3001EU\u306e\u578b\u5f0f\u8a8d\u8a3c\u3084\u96fb\u6c17\u81ea\u52d5\u8eca\u306e\u4ed5\u69d8\u304c\u6c42\u3081\u308b\u3053\u3068\u304b\u3089\u30ad\u30ed\u30ef\u30c3\u30c8\uff08kW\uff09\u8868\u8a18\u3082\u5897\u3048\u3066\u3044\u307e\u3059\u3002\u5bb6\u96fb\u3084\u30dd\u30f3\u30d7\u306f\u901a\u5e38\u3001\u9298\u677f\u306b\u30ef\u30c3\u30c8\u307e\u305f\u306f hp \u3067\u8a18\u8f09\u3055\u308c\u3001\u30a8\u30a2\u30b3\u30f3\u3084\u6696\u623f\u6a5f\u306f BTU/h \u3067\u8868\u3055\u308c\u307e\u3059\u3002\u3053\u308c\u3089\u306f\u5225\u3005\u306e\u7269\u7406\u91cf\u3067\u306f\u306a\u304f\u3001\u3059\u3079\u3066\u30a8\u30cd\u30eb\u30ae\u30fc\u306e\u4f1d\u9054\u7387\u3001\u3064\u307e\u308a\u51fa\u529b\u3067\u3059\u3002\u3057\u304b\u3057\u8a18\u61b6\u306b\u983c\u3063\u3066\u63db\u7b97\u3057\u305f\u9014\u7aef\u306b\u30b9\u30da\u30c3\u30af\u8868\u306e\u9593\u9055\u3044\u304c\u8d77\u3053\u308a\u307e\u3059\u3002\u3068\u304f\u306b\u4e00\u898b\u540c\u3058\u306b\u898b\u3048\u3066\u5b9f\u306f\u9055\u3046 hp \u3068 PS \u306e\u9593\u3067\u8d77\u304d\u304c\u3061\u3067\u3059\u3002</p>\n\n    <h3>\u4f7f\u3044\u65b9</h3>\n    <ol>\n      <li>\u624b\u5143\u306e\u6570\u5024\u3092\u5165\u529b\u3057\u307e\u3059 \u2014 \u305f\u3068\u3048\u3070\u30a8\u30f3\u30b8\u30f3\u4ed5\u69d8\u306e hp \u306e\u5024\u3084\u3001\u5bb6\u96fb\u30e9\u30d9\u30eb\u306e\u30ef\u30c3\u30c8\u6570\u3067\u3059\u3002</li>\n      <li><strong>\u5909\u63db\u5143</strong>\u306b\u305d\u306e\u6570\u5024\u306e\u5358\u4f4d\u3092\u3001<strong>\u5909\u63db\u5148</strong>\u306b\u6c42\u3081\u305f\u3044\u5358\u4f4d\u3092\u8a2d\u5b9a\u3057\u307e\u3059\u3002\u5165\u308c\u66ff\u3048\u30dc\u30bf\u30f3\uff08\u21c4\uff09\u3092\u62bc\u3059\u3068\u4e21\u65b9\u304c\u4e00\u5ea6\u306b\u5207\u308a\u66ff\u308f\u308a\u307e\u3059\u3002</li>\n      <li>\u5f37\u8abf\u8868\u793a\u3055\u308c\u305f\u7d50\u679c\u3092\u8aad\u3080\u304b\u3001\u4e0b\u306e\u8868\u3092\u305f\u3069\u3063\u3066\u540c\u3058\u5024\u304c7\u5358\u4f4d\u3067\u540c\u6642\u306b\u8868\u793a\u3055\u308c\u3066\u3044\u308b\u306e\u3092\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002</li>\n    </ol>\n\n    <h3>\u8a08\u7b97\u306e\u4e2d\u8eab\uff1a\u306a\u305c hp \u2260 PS \u306a\u306e\u304b</h3>\n    <p>\u3053\u3053\u3067\u306e\u63db\u7b97\u306f\u3059\u3079\u3066\u30ef\u30c3\u30c8\uff08W\uff09\u3092\u5171\u901a\u306e\u57fa\u6e96\u3068\u3057\u3066\u7d4c\u7531\u3057\u3001\u5404\u4fc2\u6570\u306f\u4e38\u3081\u305f\u6982\u7b97\u3067\u306f\u306a\u304f\u53b3\u5bc6\u306a\u5b9a\u7fa9\u306b\u57fa\u3065\u3044\u3066\u3044\u307e\u3059\u3002\u6a5f\u68b0\u99ac\u529b\uff08hp\uff09\u306f\u30b8\u30a7\u30fc\u30e0\u30ba\u30fb\u30ef\u30c3\u30c8\u304c\u88fd\u7c89\u6240\u306e\u99ac\u3092\u3082\u3068\u306b\u5b9a\u7fa9\u3057\u305f\u3082\u306e\u3067\u3001\u6b63\u78ba\u306b<strong>\u6bce\u79d2550\u30d5\u30a3\u30fc\u30c8\u30dd\u30f3\u30c9\u306e\u4ed5\u4e8b</strong>\u3068\u3057\u3066\u6a19\u6e96\u5316\u3055\u308c\u3001745.6998715822702 W \u306b\u76f8\u5f53\u3057\u307e\u3059\u3002\u30e1\u30fc\u30c8\u30eb\u99ac\u529b\uff08PS\u3001\u30c9\u30a4\u30c4\u8a9e <em>Pferdest\u00e4rke</em>\u3001cv \u3084 hp(M) \u3068\u3082\u8868\u8a18\uff09\u306f\u6a19\u6e96\u91cd\u529b\uff089.80665 m/s\u00b2\uff09\u3092\u7528\u3044\u3066<strong>\u6bce\u79d275\u30ad\u30ed\u30b0\u30e9\u30e0\u91cd\u30e1\u30fc\u30c8\u30eb</strong>\u3068\u5b9a\u7fa9\u3055\u308c\u3001\u6b63\u78ba\u306b 735.49875 W \u306b\u306a\u308a\u307e\u3059\u3002\u4e8c\u3064\u306e\u5b9a\u7fa9\u304c\u7570\u306a\u308b\u57fa\u672c\u5358\u4f4d\uff08\u30e4\u30fc\u30c9\u30fb\u30dd\u30f3\u30c9\u6cd5\u306e\u30d5\u30a3\u30fc\u30c8\u30dd\u30f3\u30c9\u5bfe\u30e1\u30fc\u30c8\u30eb\u6cd5\u306e\u30ad\u30ed\u30b0\u30e9\u30e0\u91cd\uff09\u304b\u3089\u51fa\u767a\u3059\u308b\u305f\u3081\u3001\u7d041.39%\u306e\u5dee\u304c\u751f\u307e\u308c\u307e\u3059 \u2014 \u6df7\u540c\u3059\u308b\u307b\u3069\u8fd1\u304f\u3001\u3057\u304b\u3057\u30b9\u30da\u30c3\u30af\u8868\u3067\u306f\u7121\u8996\u3067\u304d\u306a\u3044\u307b\u3069\u96e2\u308c\u305f\u5dee\u3067\u3059\u3002</p>\n\n    <h3>\u8a08\u7b97\u4f8b</h3>\n    <div class=\"example\"><strong>1. \u6b27\u5dde\u306e\u30b9\u30da\u30c3\u30af\u8868\u3068\u7c73\u56fd\u306e\u30b9\u30da\u30c3\u30af\u8868\u3092\u6bd4\u3079\u308b\u3002</strong> \u30c9\u30a4\u30c4\u3067\u300c150 PS\u300d\u3068\u8868\u8a18\u3055\u308c\u305f\u8eca\uff1a150 \u00d7 735.49875 = 110,324.8 W \u2248 <strong>110.32 kW</strong> \u2248 <strong>147.95 hp</strong>\u3002\u3064\u307e\u308a\u300c150 PS\u300d\u306f\u300c150 hp\u300d\u3067\u306f\u306a\u304f\u3001148 hp \u3092\u308f\u305a\u304b\u306b\u4e0b\u56de\u308a\u307e\u3059\u3002\u7570\u306a\u308b\u5358\u4f4d\u3067\u8868\u8a18\u3055\u308c\u305f\u30a8\u30f3\u30b8\u30f3\u3092\u6bd4\u8f03\u691c\u8a0e\u3059\u308b\u969b\u306b\u77e5\u3063\u3066\u304a\u304f\u4fa1\u5024\u306e\u3042\u308b\u5dee\u3067\u3059\u3002</div>\n    <div class=\"example\"><strong>2. \u5bb6\u96fb\u306e\u56de\u8def\u5bb9\u91cf\u3092\u898b\u7a4d\u3082\u308b\u3002</strong> 1.5 hp \u306e\u696d\u52d9\u7528\u6383\u9664\u6a5f\u3084\u30d7\u30fc\u30eb\u30dd\u30f3\u30d7\u306e\u30e2\u30fc\u30bf\u30fc\uff1a1.5 \u00d7 745.6998715822702 \u2248 <strong>1,118.5 W</strong>\uff08\u7d04 1.12 kW\uff09\u306e\u5b9a\u683c\u6a5f\u68b0\u51fa\u529b\u3067\u3059\u3002\u30e2\u30fc\u30bf\u30fc\u306e\u52b9\u7387\u306f100%\u3067\u306f\u306a\u3044\u305f\u3081\u5b9f\u969b\u306e\u96fb\u6c17\u6d88\u8cbb\u306f\u3053\u308c\u3088\u308a\u5c11\u3057\u5927\u304d\u304f\u306a\u308a\u307e\u3059 \u2014 15 A / 1,800 W \u306e\u5bb6\u5ead\u7528\u56de\u8def\u306b\u3064\u306a\u3050\u524d\u306b\u77e5\u3063\u3066\u304a\u304f\u3068\u5f79\u7acb\u3061\u307e\u3059\u3002</div>\n    <div class=\"example\"><strong>3. \u30a8\u30a2\u30b3\u30f3\u306e BTU/h \u8868\u793a\u3092\u8aad\u3080\u3002</strong> \u300c1\u30c8\u30f3\u300d\u306e\u30a8\u30a2\u30b3\u30f3\u306f 12,000 BTU/h \u306e\u5b9a\u683c\u3067\u3059\uff1a12,000 \u00d7 0.29307107017222222 \u2248 3,516.85 W \u2248 <strong>3.517 kW</strong>\u3002\u6b27\u5dde\u88fd\u54c1\u306e kW \u8868\u8a18\u3084\u767a\u96fb\u6a5f\u306e\u51fa\u529b\u3068\u6bd4\u8f03\u3059\u308b\u3068\u304d\u306b\u4f7f\u3046\u6570\u5024\u3067\u3059\u3002</div>\n    <div class=\"example\"><strong>4. \u975e\u5e38\u7528\u767a\u96fb\u6a5f\u306e\u5bb9\u91cf\u3092\u898b\u7a4d\u3082\u308b\u3002</strong> 5 kW \u306e\u30dd\u30fc\u30bf\u30d6\u30eb\u767a\u96fb\u6a5f\u3092\u30a8\u30f3\u30b8\u30f3\u4ed5\u69d8\u3068\u306e\u6bd4\u8f03\u306e\u305f\u3081\u99ac\u529b\u306b\u63db\u7b97\u3059\u308b\u3068\uff1a5,000 \u00f7 745.6998715822702 \u2248 <strong>6.71 hp</strong> \u306e\u9023\u7d9a\u6a5f\u68b0\u51fa\u529b\u306b\u76f8\u5f53\u3057\u307e\u3059\u3002</div>\n\n    <h3>\u53c2\u8003\uff1a1 W \u3092\u57fa\u6e96\u3068\u3057\u305f\u6b63\u78ba\u306a\u63db\u7b97\u4fc2\u6570</h3>\n    <table>\n      <thead><tr><th>\u5358\u4f4d</th><th>1\u5358\u4f4d\u306eW\u5024</th><th>\u4e3b\u306a\u7528\u9014</th></tr></thead>\n      <tbody>\n        <tr><td>\u30ef\u30c3\u30c8 (W)</td><td>1\uff08\u57fa\u6e96\uff09</td><td>SI\u5358\u4f4d\u3001\u96fb\u5b50\u6a5f\u5668\u3001\u5c0f\u578b\u5bb6\u96fb</td></tr>\n        <tr><td>\u30ad\u30ed\u30ef\u30c3\u30c8 (kW)</td><td>1,000</td><td>\u30e2\u30fc\u30bf\u30fc\u3001\u767a\u96fb\u6a5f\u3001EV\u30d1\u30ef\u30fc\u30c8\u30ec\u30a4\u30f3</td></tr>\n        <tr><td>\u30e1\u30ac\u30ef\u30c3\u30c8 (MW)</td><td>1,000,000</td><td>\u767a\u96fb\u6240\u3001\u7523\u696d\u7528\u30bf\u30fc\u30d3\u30f3</td></tr>\n        <tr><td>\u99ac\u529b (hp)</td><td>745.6998715822702</td><td>\u7c73\u82f1\u306e\u30a8\u30f3\u30b8\u30f3\u3001\u30dd\u30f3\u30d7\u3001\u96fb\u52d5\u5de5\u5177</td></tr>\n        <tr><td>\u30e1\u30fc\u30c8\u30eb\u99ac\u529b (PS)</td><td>735.49875</td><td>\u6b27\u5dde\u30fb\u65e5\u672c\u30fb\u97d3\u56fd\u306e\u81ea\u52d5\u8eca\u30b9\u30da\u30c3\u30af</td></tr>\n        <tr><td>\u6bce\u6642BTU (BTU/h)</td><td>0.29307107017222222</td><td>\u30a8\u30a2\u30b3\u30f3\u3001\u6696\u623f\u6a5f\u3001\u7a7a\u8abf\u8a2d\u5099</td></tr>\n        <tr><td>\u6bce\u79d2\u30d5\u30a3\u30fc\u30c8\u30dd\u30f3\u30c9 (ft\u00b7lb/s)</td><td>1.3558179483314004</td><td>\u7269\u7406\u30fb\u529b\u5b66\u306e\u554f\u984c</td></tr>\n      </tbody>\n    </table>\n\n    <h3>\u3088\u304f\u3042\u308b\u9593\u9055\u3044</h3>\n    <ul>\n      <li><strong>hp \u3068 PS \u3092\u540c\u3058\u6570\u5024\u3068\u3057\u3066\u6271\u3046\u3002</strong> \u7d041.4%\u306e\u5dee\u3067\u8fd1\u3044\u3082\u306e\u306e\u3001\u300c300 PS\u300d\u306e\u30a8\u30f3\u30b8\u30f3\u306f\u300c300 hp\u300d\u306e\u30a8\u30f3\u30b8\u30f3\u3067\u306f\u306a\u304f\u3001296 hp \u306b\u8fd1\u3044\u5024\u3067\u3059\u3002</li>\n      <li><strong>\u51fa\u529b\u3068\u30c8\u30eb\u30af\u3092\u6df7\u540c\u3059\u308b\u3002</strong> \u30a8\u30f3\u30b8\u30f3\u306e\u4ed5\u69d8\u306b\u306f\u30c8\u30eb\u30af\uff08N\u00b7m \u307e\u305f\u306f lb-ft\uff09\u3082\u4f75\u8a18\u3055\u308c\u307e\u3059\u304c\u3001\u3053\u308c\u306f\u5225\u306e\u7269\u7406\u91cf\u3067\u3059 \u2014 \u3053\u306e\u30c4\u30fc\u30eb\u306f\u51fa\u529b\u306e\u5358\u4f4d\u3060\u3051\u3092\u63db\u7b97\u3057\u3001\u30c8\u30eb\u30af\u306f\u6271\u3044\u307e\u305b\u3093\u3002</li>\n      <li><strong>\u30e2\u30fc\u30bf\u30fc\u9298\u677f\u306e\u5b9a\u683c hp \u3092\u96fb\u6c17\u7684\u306a\u30ef\u30c3\u30c8\u3068\u540c\u4e00\u8996\u3059\u308b\u3002</strong> \u30e2\u30fc\u30bf\u30fc\u306e hp \u5b9a\u683c\u306f\u6a5f\u68b0\u51fa\u529b\u3092\u8868\u3057\u3001\u52b9\u7387\u640d\u5931\u306e\u305f\u3081\u30ef\u30c3\u30c8\u5358\u4f4d\u306e\u96fb\u6c17\u5165\u529b\u306f\u305d\u308c\u3088\u308a\u5927\u304d\u304f\u306a\u308a\u307e\u3059\u3002\u3057\u305f\u304c\u3063\u3066 hp\u2192\u30ef\u30c3\u30c8\u306e\u63db\u7b97\u3060\u3051\u3067\u30d6\u30ec\u30fc\u30ab\u30fc\u5bb9\u91cf\u3092\u6c7a\u3081\u3066\u306f\u3044\u3051\u307e\u305b\u3093\u3002</li>\n      <li><strong>BTU\uff08\u30a8\u30cd\u30eb\u30ae\u30fc\uff09\u3068 BTU/h\uff08\u51fa\u529b\uff09\u3092\u53d6\u308a\u9055\u3048\u308b\u3002</strong> BTU/h \u306f\u7387\u3001\u3064\u307e\u308a\u51fa\u529b\u3067\u3042\u308a\u3001\u5358\u306a\u308b BTU \u306f\u30a8\u30cd\u30eb\u30ae\u30fc\u306e\u5358\u4f4d\u3067\u3059\u3002\u30ef\u30c3\u30c8\u3068\u30ef\u30c3\u30c8\u6642\u304c\u4e92\u63db\u3067\u306a\u3044\u306e\u3068\u540c\u3058\u3067\u3059\u3002</li>\n    </ul>\n\n    <h3>\u3053\u306e\u30c4\u30fc\u30eb\u304c\u3067\u304d\u306a\u3044\u3053\u3068</h3>\n    <p>\u3053\u308c\u306f\u5358\u4f4d\u63db\u7b97\u30c4\u30fc\u30eb\u3067\u3042\u3063\u3066\u52b9\u7387\u8a08\u7b97\u6a5f\u3067\u306f\u3042\u308a\u307e\u305b\u3093 \u2014 \u5165\u529b\u3055\u308c\u305f\u6570\u5024\u3092\u305d\u306e\u307e\u307e\u63db\u7b97\u3059\u308b\u3060\u3051\u3067\u3001\u30e2\u30fc\u30bf\u30fc\u52b9\u7387\u3084\u99c6\u52d5\u7cfb\u306e\u640d\u5931\u3001\u30a8\u30f3\u30b8\u30f3\u306e\u5b9a\u683c\u306b\u5bfe\u3059\u308b\u5b9f\u969b\u306e\u51fa\u529b\u306f\u8003\u616e\u3067\u304d\u307e\u305b\u3093\u3002\u96fb\u6c17\u306e\u5b89\u5168\u306b\u95a2\u308f\u308b\u4f5c\u696d\uff08\u30d6\u30ec\u30fc\u30ab\u30fc\u5bb9\u91cf\u3001\u914d\u7dda\u3001\u767a\u96fb\u6a5f\u306e\u8ca0\u8377\uff09\u3067\u306f\u5fc5\u305a\u6a5f\u5668\u306e\u5b9f\u969b\u306e\u9298\u677f\u5b9a\u683c\u3092\u7528\u3044\u3001\u6709\u8cc7\u683c\u306e\u96fb\u6c17\u6280\u8853\u8005\u306b\u76f8\u8ac7\u3057\u3066\u304f\u3060\u3055\u3044\u3002\u3053\u306e\u30c4\u30fc\u30eb\u306f\u624b\u65e9\u3044\u6bd4\u8f03\u306e\u305f\u3081\u306e\u3082\u306e\u3067\u3042\u308a\u3001\u6cd5\u4ee4\u9069\u5408\u306e\u5224\u65ad\u7528\u3067\u306f\u3042\u308a\u307e\u305b\u3093\u3002</p>",
"ko": "<style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:14px}\n      .guide-content th,.guide-content td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n    </style>\n<h2>hp, PS, kW\uac00 \uc11c\ub85c \ub531 \ub9de\uc544\ub5a8\uc5b4\uc9c0\uc9c0 \uc54a\ub294 \uc774\uc720</h2>\n    <p>\ucd9c\ub825 \ud45c\uae30\ub294 \uc11c\ub85c \ub2e4\ub978 \uc138 \uac00\uc9c0 \uc804\ud1b5\uc5d0\uc11c \uc654\uace0, \uc9c0\uae08\ub3c4 \uac19\uc740 \uc0ac\uc591\ud45c\uc5d0 \ub4a4\uc11e\uc5ec \ub4f1\uc7a5\ud569\ub2c8\ub2e4. \uc790\ub3d9\ucc28 \uc5d4\uc9c4\uc740 \ubbf8\uad6d\u00b7\uc601\uad6d\uc5d0\uc11c\ub294 \ub9c8\ub825(hp), \uc720\ub7fd \ub300\ubd80\ubd84\uacfc \uc77c\ubcf8\u00b7\ud55c\uad6d\uc5d0\uc11c\ub294 \ubbf8\ud130\ub9c8\ub825(PS)\uc73c\ub85c \ud45c\uae30\ub418\uba70, EU \ud615\uc2dd\uc2b9\uc778\uacfc \uc804\uae30\ucc28 \uc0ac\uc591\uc774 \uc694\uad6c\ud558\uba74\uc11c \ud0ac\ub85c\uc640\ud2b8(kW) \ud45c\uae30\ub3c4 \ub298\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uac00\uc804\uc81c\ud488\uacfc \ud38c\ud504\ub294 \ubcf4\ud1b5 \uba85\ud310\uc5d0 \uc640\ud2b8\ub098 hp\ub85c \uc801\ud600 \uc788\uace0, \uc5d0\uc5b4\ucee8\uacfc \ubcf4\uc77c\ub7ec\ub294 BTU/h\ub85c \ud45c\uc2dc\ub429\ub2c8\ub2e4. \uc774\ub4e4\uc740 \ubaa8\ub450 \uc11c\ub85c \ub2e4\ub978 \ubb3c\ub9ac\ub7c9\uc774 \uc544\ub2c8\ub77c \uc804\ubd80 \uc5d0\ub108\uc9c0 \uc804\ub2ec\ub960, \uc989 \ucd9c\ub825\uc785\ub2c8\ub2e4. \ub2e4\ub9cc \uae30\uc5b5\uc5d0 \uc758\uc874\ud574 \ubcc0\ud658\ud558\ub294 \uc21c\uac04 \uc0ac\uc591\ud45c \uc2e4\uc218\uac00 \uc0dd\uae30\ub294\ub370, \ud2b9\ud788 \uc11c\ub85c \uac19\uc740 \uac12\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \uc2e4\uc81c\ub85c\ub294 \ub2e4\ub978 hp\uc640 PS \uc0ac\uc774\uc5d0\uc11c \uadf8\ub807\uc2b5\ub2c8\ub2e4.</p>\n\n    <h3>\uc0ac\uc6a9 \ubc29\ubc95</h3>\n    <ol>\n      <li>\uac00\uc9c0\uace0 \uc788\ub294 \uc22b\uc790\ub97c \uc785\ub825\ud558\uc138\uc694 \u2014 \uc608\ub97c \ub4e4\uc5b4 \uc5d4\uc9c4 \uc0ac\uc591\uc758 hp \uac12\uc774\ub098 \uac00\uc804\uc81c\ud488 \ub77c\ubca8\uc758 \uc640\ud2b8 \uc218\uc785\ub2c8\ub2e4.</li>\n      <li><strong>\ubcc0\ud658 \uc804</strong>\uc5d0\ub294 \uadf8 \uc22b\uc790\uc758 \ud604\uc7ac \ub2e8\uc704\ub97c, <strong>\ubcc0\ud658 \ud6c4</strong>\uc5d0\ub294 \uc6d0\ud558\ub294 \ub2e8\uc704\ub97c \uc9c0\uc815\ud569\ub2c8\ub2e4. \uad50\uccb4 \ubc84\ud2bc(\u21c4)\uc744 \ub204\ub974\uba74 \ub450 \ub2e8\uc704\uac00 \ud55c \ubc88\uc5d0 \ubc14\ub01d\ub2c8\ub2e4.</li>\n      <li>\uac15\uc870\ub41c \uacb0\uacfc\ub97c \uc77d\uac70\ub098, \uc544\ub798 \ud45c\ub97c \uc0b4\ud3b4 \uac19\uc740 \uac12\uc774 7\uac1c \ub2e8\uc704\ub85c \ub3d9\uc2dc\uc5d0 \ud45c\ud604\ub41c \uac83\uc744 \ud655\uc778\ud558\uc138\uc694.</li>\n    </ol>\n\n    <h3>\uacc4\uc0b0 \uc6d0\ub9ac: hp \u2260 PS\uc778 \uae4c\ub2ed</h3>\n    <p>\uc5ec\uae30\uc11c \ubaa8\ub4e0 \ubcc0\ud658\uc740 \uc640\ud2b8(W)\ub97c \uacf5\ud1b5 \uae30\uc900\uc73c\ub85c \uac70\uce58\uba70, \uac01 \uacc4\uc218\ub294 \ubc18\uc62c\ub9bc\ud55c \ucd94\uc815\uac12\uc774 \uc544\ub2c8\ub77c \uc815\ud655\ud55c \uc815\uc758\uc5d0\uc11c \ub098\uc635\ub2c8\ub2e4. \uae30\uacc4\ub9c8\ub825(hp)\uc740 \uc81c\uc784\uc2a4 \uc640\ud2b8\uac00 \ubc29\uc557\uac04\uc758 \ub9d0\uc744 \uae30\uc900\uc73c\ub85c \uc815\uc758\ud588\uace0 \uc815\ud655\ud788 <strong>\ucd08\ub2f9 550 \ud53c\ud2b8\ud30c\uc6b4\ub4dc\uc758 \uc77c</strong>\ub85c \ud45c\uc900\ud654\ub418\uc5c8\ub294\ub370, \uc774\ub294 745.6998715822702 W\uc5d0 \ud574\ub2f9\ud569\ub2c8\ub2e4. \ubbf8\ud130\ub9c8\ub825(PS, \ub3c5\uc77c\uc5b4 <em>Pferdest\u00e4rke</em>, cv \ub610\ub294 hp(M)\ub85c\ub3c4 \ud45c\uae30)\uc740 \ud45c\uc900\uc911\ub825(9.80665 m/s\u00b2)\uc744 \uc0ac\uc6a9\ud574 <strong>\ucd08\ub2f9 75 \ud0ac\ub85c\uadf8\ub7a8\ud798\u00b7\ubbf8\ud130</strong>\ub85c \uc815\uc758\ub418\uba70, \uc815\ud655\ud788 735.49875 W\uac00 \ub429\ub2c8\ub2e4. \ub450 \uc815\uc758\uac00 \uc11c\ub85c \ub2e4\ub978 \uae30\ubcf8 \ub2e8\uc704(\uc57c\ub4dc\ud30c\uc6b4\ub4dc\uacc4\uc758 \ud53c\ud2b8\ud30c\uc6b4\ub4dc \ub300 \ubbf8\ud130\ubc95\uc758 \ud0ac\ub85c\uadf8\ub7a8\ud798)\uc5d0\uc11c \ucd9c\ubc1c\ud558\uae30 \ub54c\ubb38\uc5d0 \uc57d 1.39% \ucc28\uc774\uac00 \ub0a9\ub2c8\ub2e4 \u2014 \ud5f7\uac08\ub9b4 \ub9cc\ud07c \uac00\uae5d\uc9c0\ub9cc, \uc0ac\uc591\ud45c\uc5d0\uc11c\ub294 \ubb34\uc2dc\ud560 \uc218 \uc5c6\uc744 \ub9cc\ud07c \uba3c \ucc28\uc774\uc785\ub2c8\ub2e4.</p>\n\n    <h3>\uacc4\uc0b0 \uc608\uc2dc</h3>\n    <div class=\"example\"><strong>1. \uc720\ub7fd \uc0ac\uc591\ud45c\uc640 \ubbf8\uad6d \uc0ac\uc591\ud45c \ube44\uad50.</strong> \ub3c5\uc77c\uc5d0\uc11c \"150 PS\"\ub85c \ud45c\uae30\ub41c \ucc28: 150 \u00d7 735.49875 = 110,324.8 W \u2248 <strong>110.32 kW</strong> \u2248 <strong>147.95 hp</strong>. \uc989 \"150 PS\"\ub294 \"150 hp\"\uac00 \uc544\ub2c8\ub77c 148 hp\uc5d0 \uc0b4\uc9dd \ubabb \ubbf8\uce69\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ub2e8\uc704\ub85c \ud45c\uae30\ub41c \uc5d4\uc9c4\uc744 \ube44\uad50\ud560 \ub54c \uc54c\uc544\ub458 \ub9cc\ud55c \ucc28\uc774\uc785\ub2c8\ub2e4.</div>\n    <div class=\"example\"><strong>2. \uac00\uc804 \ud68c\ub85c \uc6a9\ub7c9 \uacc4\uc0b0.</strong> 1.5 hp\uc9dc\ub9ac \uc791\uc5c5\uc7a5 \uc9c4\uacf5\uccad\uc18c\uae30\ub098 \uc218\uc601\uc7a5 \ud38c\ud504 \ubaa8\ud130: 1.5 \u00d7 745.6998715822702 \u2248 <strong>1,118.5 W</strong>(\uc57d 1.12 kW)\uc758 \uc815\uaca9 \uae30\uacc4 \ucd9c\ub825\uc785\ub2c8\ub2e4. \ubaa8\ud130 \ud6a8\uc728\uc774 100%\uac00 \uc544\ub2c8\ubbc0\ub85c \uc2e4\uc81c \uc804\uae30 \uc18c\ube44\ub294 \uc774\ubcf4\ub2e4 \uc870\uae08 \ub192\uc2b5\ub2c8\ub2e4 \u2014 15 A / 1,800 W \uac00\uc815\uc6a9 \ud68c\ub85c\uc5d0 \uc5f0\uacb0\ud558\uae30 \uc804\uc5d0 \uc54c\uc544\ub450\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</div>\n    <div class=\"example\"><strong>3. \uc5d0\uc5b4\ucee8\uc758 BTU/h \ud45c\uae30 \uc77d\uae30.</strong> \"1\ud1a4\" \uc5d0\uc5b4\ucee8\uc740 12,000 BTU/h \uc815\uaca9\uc785\ub2c8\ub2e4: 12,000 \u00d7 0.29307107017222222 \u2248 3,516.85 W \u2248 <strong>3.517 kW</strong>. \uc720\ub7fd \uc81c\ud488\uc758 kW \ud45c\uae30\ub098 \ubc1c\uc804\uae30 \ucd9c\ub825\uacfc \ube44\uad50\ud560 \ub54c \uc4f0\ub294 \uac12\uc785\ub2c8\ub2e4.</div>\n    <div class=\"example\"><strong>4. \ube44\uc0c1 \ubc1c\uc804\uae30 \uc6a9\ub7c9 \uacc4\uc0b0.</strong> 5 kW \uc774\ub3d9\uc2dd \ubc1c\uc804\uae30\ub97c \uc5d4\uc9c4 \uc0ac\uc591 \ube44\uad50\uc6a9\uc73c\ub85c \ub9c8\ub825\uc73c\ub85c \ud658\uc0b0\ud558\uba74: 5,000 \u00f7 745.6998715822702 \u2248 <strong>6.71 hp</strong>\uc758 \uc5f0\uc18d \uae30\uacc4 \ucd9c\ub825\uc5d0 \ud574\ub2f9\ud569\ub2c8\ub2e4.</div>\n\n    <h3>\ucc38\uace0: 1 W \uae30\uc900 \uc815\ud655\ud55c \ubcc0\ud658 \uacc4\uc218</h3>\n    <table>\n      <thead><tr><th>\ub2e8\uc704</th><th>1\ub2e8\uc704\uc758 W \uac12</th><th>\uc8fc\uc694 \uc6a9\ub3c4</th></tr></thead>\n      <tbody>\n        <tr><td>\uc640\ud2b8 (W)</td><td>1 (\uae30\uc900)</td><td>SI \ub2e8\uc704, \uc804\uc790\uae30\uae30, \uc18c\ud615 \uac00\uc804</td></tr>\n        <tr><td>\ud0ac\ub85c\uc640\ud2b8 (kW)</td><td>1,000</td><td>\ubaa8\ud130, \ubc1c\uc804\uae30, \uc804\uae30\ucc28 \uad6c\ub3d9\uacc4</td></tr>\n        <tr><td>\uba54\uac00\uc640\ud2b8 (MW)</td><td>1,000,000</td><td>\ubc1c\uc804\uc18c, \uc0b0\uc5c5\uc6a9 \ud130\ube48</td></tr>\n        <tr><td>\ub9c8\ub825 (hp)</td><td>745.6998715822702</td><td>\ubbf8\uad6d\u00b7\uc601\uad6d \uc5d4\uc9c4, \ud38c\ud504, \uc804\ub3d9\uacf5\uad6c</td></tr>\n        <tr><td>\ubbf8\ud130\ub9c8\ub825 (PS)</td><td>735.49875</td><td>\uc720\ub7fd\u00b7\uc77c\ubcf8\u00b7\ud55c\uad6d \uc790\ub3d9\ucc28 \uc0ac\uc591</td></tr>\n        <tr><td>\uc2dc\uac04\ub2f9 BTU (BTU/h)</td><td>0.29307107017222222</td><td>\uc5d0\uc5b4\ucee8, \ubcf4\uc77c\ub7ec, \uacf5\uc870 \uc124\ube44</td></tr>\n        <tr><td>\ucd08\ub2f9 \ud53c\ud2b8\ud30c\uc6b4\ub4dc (ft\u00b7lb/s)</td><td>1.3558179483314004</td><td>\ubb3c\ub9ac\u00b7\uc5ed\ud559 \ubb38\uc81c</td></tr>\n      </tbody>\n    </table>\n\n    <h3>\ud754\ud55c \uc2e4\uc218</h3>\n    <ul>\n      <li><strong>hp\uc640 PS\ub97c \uac19\uc740 \uc22b\uc790\ub85c \ucde8\uae09\ud558\uae30.</strong> \uc57d 1.4% \ucc28\uc774\ub85c \uac00\uae5d\uc9c0\ub9cc \"300 PS\" \uc5d4\uc9c4\uc740 \"300 hp\" \uc5d4\uc9c4\uc774 \uc544\ub2c8\ub77c 296 hp\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.</li>\n      <li><strong>\ucd9c\ub825\uacfc \ud1a0\ud06c \ud63c\ub3d9\ud558\uae30.</strong> \uc5d4\uc9c4 \uc0ac\uc591\uc5d0\ub294 \ud1a0\ud06c(N\u00b7m \ub610\ub294 lb-ft)\ub3c4 \ud568\uaed8 \uc801\ud788\ub294\ub370 \uc774\ub294 \ub2e4\ub978 \ubb3c\ub9ac\ub7c9\uc785\ub2c8\ub2e4 \u2014 \uc774 \ub3c4\uad6c\ub294 \ucd9c\ub825 \ub2e8\uc704\ub9cc \ubcc0\ud658\ud558\uba70 \ud1a0\ud06c\ub294 \ub2e4\ub8e8\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.</li>\n      <li><strong>\ubaa8\ud130 \uba85\ud310\uc758 \uc815\uaca9 hp\ub97c \uc804\uae30 \uc640\ud2b8\uc640 \uac19\ub2e4\uace0 \uac00\uc815\ud558\uae30.</strong> \ubaa8\ud130\uc758 hp \uc815\uaca9\uc740 \uae30\uacc4 \ucd9c\ub825\uc744 \ub73b\ud558\uba70, \ud6a8\uc728 \uc190\uc2e4 \ub54c\ubb38\uc5d0 \uc640\ud2b8 \ub2e8\uc704\uc758 \uc804\uae30 \uc785\ub825\uc740 \ub354 \ud07d\ub2c8\ub2e4. \ub530\ub77c\uc11c hp\u2192\uc640\ud2b8 \ubcc0\ud658\ub9cc\uc73c\ub85c \ucc28\ub2e8\uae30 \uc6a9\ub7c9\uc744 \uc815\ud558\uba74 \uc548 \ub429\ub2c8\ub2e4.</li>\n      <li><strong>BTU(\uc5d0\ub108\uc9c0)\uc640 BTU/h(\ucd9c\ub825) \ud5f7\uac08\ub9ac\uae30.</strong> BTU/h\ub294 \ube44\uc728, \uc989 \ucd9c\ub825\uc774\uace0 \uadf8\ub0e5 BTU\ub294 \uc5d0\ub108\uc9c0 \ub2e8\uc704\uc785\ub2c8\ub2e4. \uc640\ud2b8\uc640 \uc640\ud2b8\uc2dc\uac00 \uc11c\ub85c \ubc14\uafd4 \uc4f8 \uc218 \uc5c6\ub294 \uac83\uacfc \uac19\uc2b5\ub2c8\ub2e4.</li>\n    </ul>\n\n    <h3>\uc774 \ub3c4\uad6c\uac00 \ud558\uc9c0 \uc54a\ub294 \uc77c</h3>\n    <p>\uc774\uac83\uc740 \ub2e8\uc704 \ubcc0\ud658\uae30\uc774\uc9c0 \ud6a8\uc728 \uacc4\uc0b0\uae30\uac00 \uc544\ub2d9\ub2c8\ub2e4 \u2014 \uc785\ub825\ud55c \uc22b\uc790\ub97c \uc561\uba74 \uadf8\ub300\ub85c \ubcc0\ud658\ud560 \ubfd0, \ubaa8\ud130 \ud6a8\uc728\uc774\ub098 \uad6c\ub3d9\uacc4 \uc190\uc2e4, \uc5d4\uc9c4\uc758 \uc815\uaca9 \ub300\ube44 \uc2e4\uc81c \ucd9c\ub825\uc740 \ubc18\uc601\ud558\uc9c0 \ubabb\ud569\ub2c8\ub2e4. \uc804\uae30 \uc548\uc804 \uc791\uc5c5(\ucc28\ub2e8\uae30 \uc6a9\ub7c9, \ubc30\uc120, \ubc1c\uc804\uae30 \ubd80\ud558)\uc5d0\ub294 \ubc18\ub4dc\uc2dc \uc7a5\ube44\uc758 \uc2e4\uc81c \uba85\ud310 \uc815\uaca9\uc744 \uc0ac\uc6a9\ud558\uace0 \uc790\uaca9\uc744 \uac16\ucd98 \uc804\uae30 \uae30\uc220\uc790\uc640 \uc0c1\uc758\ud558\uc138\uc694. \uc774 \ub3c4\uad6c\ub294 \ube60\ub978 \ube44\uad50\uc6a9\uc774\uba70 \ubc95\uaddc \uc900\uc218 \ud310\ub2e8\uc6a9\uc774 \uc544\ub2d9\ub2c8\ub2e4.</p>",};
